window.GRAM={"units": {"A1-U0": {"title": "欢迎加入", "intro": "Nico 刚到德国。这一单元你学会了：跟人打招呼和道别、分清 Sie 和 du、名词的三种性，以及用字母拼写名字。", "points": [{"id": "p1", "title": "Sie 还是 du？", "rule": "对陌生人、在正式场合用 Sie（您）；对朋友、家人、孩子用 du（你）。Sie 表示“您”时永远大写。用 Sie 的时候，动词也跟着变。", "table": [["", "正式（Sie）", "熟人（du）"], ["你好吗？", "Wie geht es Ihnen?", "Wie geht's (dir)?"], ["那你呢？", "Und Ihnen?", "Und dir?"], ["需要帮忙吗？", "Brauchen Sie Hilfe?", "Brauchst du Hilfe?"], ["称呼", "Herr / Frau + 姓", "名字"]], "ex": [{"de": "Guten Morgen, Herr Müller, wie geht es Ihnen?", "zh": "早上好，Müller 先生，您好吗？"}, {"de": "Hallo, Sarah. Wie geht's dir?", "zh": "你好，Sarah。你好吗？"}], "pit": "Herr / Frau 后面接姓，不接名字：Frau Schneider ✓，Frau Sarah ✗。"}, {"id": "p2", "title": "打招呼与告别", "rule": "见面问候看时间，告别看场合：熟人之间说 Tschüss / Bis bald，正式场合说 Auf Wiedersehen。", "table": [["场合", "说法", "意思"], ["上午见面", "Guten Morgen!", "早上好"], ["白天见面", "Guten Tag!", "您好 / 日安"], ["晚上见面", "Guten Abend!", "晚上好"], ["熟人见面", "Hallo! / Hi! / Hey!", "嗨"], ["熟人告别", "Tschüss! / Bis bald! / Mach's gut!", "拜拜 / 回头见 / 保重"], ["正式告别", "Auf Wiedersehen!", "再见"], ["送人出行", "Gute Reise!", "一路顺风"]], "ex": [{"de": "Tschüss, Martina. Gute Reise!", "zh": "拜拜，Martina。一路顺风！"}, {"de": "Auf Wiedersehen, Frau Scholl.", "zh": "再见，Scholl 女士。"}], "pit": "Gute Nacht! 只在晚上道别或睡前说，见面打招呼不用。"}, {"id": "p3", "title": "der · die · das", "rule": "德语每个名词都有性：阳性 der、阴性 die、中性 das。名词首字母一律大写。记单词时把冠词一起记。", "table": [["阳性 der", "阴性 die", "中性 das"], ["der Mann", "die Frau", "das Taxi"], ["der Flughafen", "die Tasche", "das Hotel"], ["der Bus", "die Musik", "das Problem"]], "ex": [{"de": "Die Tasche ist schön!", "zh": "这个包真漂亮！"}, {"de": "Das Taxi fährt ins Zentrum.", "zh": "出租车开往市中心。"}], "pit": "人一般按自然性别：der Mann、die Frau。物品的性大多没有道理，要跟冠词一起背。小线索：-e 结尾多是 die（die Tasche），-ik 结尾是 die（die Musik）。"}, {"id": "p4", "title": "字母与拼写", "rule": "问怎么写：Wie schreibt man das? 请对方拼写：Buchstabieren Sie bitte! / Bitte buchstabiere das!", "table": [["字母", "德语读法"], ["C", "tse"], ["E", "e（像“诶”）"], ["I", "i（像“衣”）"], ["J", "jot"], ["V", "fau"], ["W", "we"], ["Y", "üpsilon"], ["Z", "tset"], ["ß", "es-tset"]], "ex": [{"de": "Wie schreibt man das?", "zh": "这个怎么写？"}, {"de": "Mein Name ist Nico: N – I – C – O.", "zh": "我叫 Nico，N-I-C-O。"}], "pit": "E 读“诶”，I 读“衣”，和英语正好相反；W 读 we，V 读 fau。"}], "test": [{"id": "A1-U0-T01", "t": "pick", "p": "p1", "q": "Frau Kamp, wie geht es ___?", "a": "Ihnen", "o": ["dir", "du"], "zh": "Kamp 女士，您好吗？", "why": "对“Frau + 姓”的人用 Sie，“您好吗”是 Wie geht es Ihnen?"}, {"id": "A1-U0-T02", "t": "pick", "p": "p1", "q": "Hey, Lena! Wie geht's ___?", "a": "dir", "o": ["Ihnen", "Sie"], "zh": "嘿，Lena！你好吗？", "why": "叫名字、说 Hey 的是熟人，用 du，所以是 dir。"}, {"id": "A1-U0-T03", "t": "trans", "p": "p1", "src": "Brauchst du Hilfe?", "cue": "对 Herr Tillmanns 说（正式）", "q": "___ Sie Hilfe?", "a": "Brauchen", "o": ["Brauchst", "Braucht"], "zh": "您需要帮忙吗？", "why": "换成 Sie，动词也要换成 Sie 的形式：brauchen。"}, {"id": "A1-U0-T04", "t": "fix", "p": "p1", "s": "Guten Tag, Frau Lisa!", "bad": "Lisa", "a": "Brunner", "o": ["Lena", "Emma"], "zh": "您好，Brunner 女士！", "why": "Frau 后面接姓，不接名字：Lisa Brunner → Frau Brunner。"}, {"id": "A1-U0-T05", "t": "pick", "p": "p2", "q": "早上 8 点在机场：___, Herr Müller!", "a": "Guten Morgen", "o": ["Guten Abend", "Gute Nacht"], "zh": "早上好，Müller 先生！", "why": "上午见面说 Guten Morgen。"}, {"id": "A1-U0-T06", "t": "pick", "p": "p2", "q": "朋友要去旅行：Tschüss, Martina. ___!", "a": "Gute Reise", "o": ["Guten Tag", "Gute Nacht"], "zh": "拜拜，Martina。一路顺风！", "why": "送人出行说 Gute Reise!"}, {"id": "A1-U0-T07", "t": "order", "p": "p2", "tiles": ["Wiedersehen", "Auf", "Frau", "Scholl"], "a": "Auf Wiedersehen, Frau Scholl!", "zh": "再见，Scholl 女士！", "why": "正式告别：Auf Wiedersehen + 称呼。"}, {"id": "A1-U0-T08", "t": "pick", "p": "p3", "q": "___ Tasche ist schön!", "a": "Die", "o": ["Der", "Das"], "zh": "这个包真漂亮！", "why": "die Tasche：-e 结尾，阴性。"}, {"id": "A1-U0-T09", "t": "sort", "p": "p3", "q": "按冠词分类", "cats": ["der", "die", "das"], "items": [{"w": "Flughafen", "c": 0}, {"w": "Bus", "c": 0}, {"w": "Musik", "c": 1}, {"w": "Toilette", "c": 1}, {"w": "Taxi", "c": 2}, {"w": "Hotel", "c": 2}], "why": "der Flughafen, der Bus · die Musik, die Toilette · das Taxi, das Hotel"}, {"id": "A1-U0-T10", "t": "fix", "p": "p3", "s": "Das Hotel ist im zentrum.", "bad": "zentrum", "a": "Zentrum", "o": ["ZENTRUM", "Zentren"], "zh": "酒店在市中心。", "why": "名词首字母一律大写：das Zentrum。"}, {"id": "A1-U0-T11", "t": "pick", "p": "p3", "q": "Tasche、Toilette、Adresse 都以 -e 结尾，冠词多半是 ___", "a": "die", "o": ["der", "das"], "why": "-e 结尾的名词大约九成是 die。"}, {"id": "A1-U0-T12", "t": "type", "p": "p4", "say": "En. I. Tse. O.", "q": "听拼写，写出这个名字：___", "a": "Nico", "why": "N – I – C – O，C 读作 tse。"}, {"id": "A1-U0-T13", "t": "pick", "p": "p4", "q": "德语字母 „Jot“ 是：___", "a": "J", "o": ["Y", "G"], "why": "J 读 jot，Y 读 üpsilon，G 读 ge。"}, {"id": "A1-U0-T14", "t": "pick", "p": "p4", "q": "请朋友拼写：Bitte ___ das!", "a": "buchstabiere", "o": ["schreibt", "heißt"], "zh": "请拼一下！", "why": "buchstabieren = 拼写；对 du 的请求用词干形式 buchstabiere。"}, {"id": "A1-U0-T15", "t": "order", "p": "p4", "tiles": ["man", "Wie", "das", "schreibt"], "a": "Wie schreibt man das?", "zh": "这个怎么写？", "why": "W 问句：疑问词第一，动词第二。"}]}, "A1-U1": {"title": "认识新朋友", "intro": "Nico 认识了 Lisa、Emma 和 Max。这一单元你学会了：介绍自己和别人、动词随人称变化、用 haben 说“有”，以及 ein / kein。", "points": [{"id": "p1", "title": "heißen 和 sein", "rule": "动词跟着人称变。heißen（叫）有规律，sein（是）完全不规则，要整张背下来。", "table": [["人称", "heißen", "sein"], ["ich 我", "heiße", "bin"], ["du 你", "heißt", "bist"], ["er / sie 他 / 她", "heißt", "ist"], ["wir 我们", "heißen", "sind"], ["Sie 您 / sie 他们", "heißen", "sind"]], "ex": [{"de": "Hallo, ich heiße Nico.", "zh": "你好，我叫 Nico。"}, {"de": "Das ist Emma. Sie ist acht.", "zh": "这是 Emma。她八岁。"}], "pit": "heißen 的 du 形式是 heißt，不是 heißst：词干已经以 ß 结尾，只加 -t。"}, {"id": "p2", "title": "er / sie 与男女称呼", "rule": "说男人用 er，说女人用 sie。很多职业名词加 -in 变成女性：der Taxifahrer → die Taxifahrerin。复合词的冠词跟最后一个词走。", "table": [["男（er）", "女（sie）"], ["der Taxifahrer", "die Taxifahrerin"], ["der Deutschlehrer", "die Deutschlehrerin"], ["der Polizist", "die Polizistin"], ["der Tourist", "die Touristin"]], "ex": [{"de": "Er ist Taxifahrer. Sie ist Taxifahrerin.", "zh": "他是出租车司机。她是女出租车司机。"}, {"de": "der Vorname, der Familienname", "zh": "名字，姓（都跟着 der Name）"}], "pit": "复合词看最后一个词：das Taxi + der Fahrer = der Taxifahrer；die Familie + der Name = der Familienname。"}, {"id": "p3", "title": "规则动词与 W 问句", "rule": "规则动词去掉 -en 得到词干，再按人称加词尾。W 问句：疑问词第一位，动词第二位。", "table": [["人称", "kommen", "wohnen", "machen"], ["ich", "komme", "wohne", "mache"], ["du", "kommst", "wohnst", "machst"], ["er / sie", "kommt", "wohnt", "macht"], ["wir / Sie", "kommen", "wohnen", "machen"]], "ex": [{"de": "Woher kommst du? – Ich komme aus Spanien.", "zh": "你从哪里来？——我来自西班牙。"}, {"de": "Wo wohnst du? – Ich wohne in Sevilla.", "zh": "你住在哪里？——我住在塞维利亚。"}], "pit": "Woher = 从哪里（来），Wo = 在哪里。动词永远在第二位：Woher kommst du?"}, {"id": "p4", "title": "haben 和 ein / eine / kein", "rule": "haben（有）也不规则：ich habe · du hast · er/sie hat · wir/Sie haben。ein / eine 是“一个”，否定用 kein / keine：der、das 名词用 ein / kein，die 名词用 eine / keine。", "table": [["", "der 名词", "die 名词", "das 名词"], ["一个", "ein Pass", "eine Tasche", "ein Foto"], ["没有", "kein Pass", "keine Tasche", "kein Foto"]], "ex": [{"de": "Nico hat ein Problem.", "zh": "Nico 遇到了一个麻烦。"}, {"de": "Da ist keine Tasche.", "zh": "那里没有包。"}], "pit": "在 haben 后面，der 名词要变成 einen / keinen：Hast du einen Pass? Ich habe keinen Pass.（第 23 集细讲第四格）"}], "test": [{"id": "A1-U1-T01", "t": "pick", "p": "p1", "q": "Mein Name ist Max. Ich ___ Max.", "a": "heiße", "o": ["heißt", "heißen"], "zh": "我的名字是 Max。我叫 Max。", "why": "ich 的词尾是 -e：ich heiße。"}, {"id": "A1-U1-T02", "t": "pick", "p": "p1", "q": "___ Sie Frau Kamp?", "a": "Sind", "o": ["Bist", "Ist"], "zh": "您是 Kamp 女士吗？", "why": "Sie（您）用 sind。"}, {"id": "A1-U1-T03", "t": "fix", "p": "p1", "s": "Ich bist Lisa.", "bad": "bist", "a": "bin", "o": ["ist", "sind"], "zh": "我是 Lisa。", "why": "ich bin · du bist · er/sie ist。"}, {"id": "A1-U1-T04", "t": "type", "p": "p1", "q": "Max ___ Lisas Freund.", "hint": "sein", "a": "ist", "zh": "Max 是 Lisa 的朋友。", "why": "er/sie 用 ist。"}, {"id": "A1-U1-T05", "t": "pick", "p": "p2", "q": "Das ist der Taxifahrer. ___ ist sauer.", "a": "Er", "o": ["Sie", "Es"], "zh": "这是那个出租车司机。他很生气。", "why": "der Taxifahrer 是男人 → er。"}, {"id": "A1-U1-T06", "t": "pick", "p": "p2", "q": "Sie ist Polizistin, er ist ___.", "a": "Polizist", "o": ["Polizistin", "Polizisten"], "zh": "她是女警察，他是警察。", "why": "男性是 der Polizist，女性加 -in：die Polizistin。"}, {"id": "A1-U1-T07", "t": "pick", "p": "p2", "q": "die Familie + der Name → ___ Familienname", "a": "der", "o": ["die", "das"], "zh": "姓", "why": "复合词的冠词看最后一个词：der Name → der Familienname。"}, {"id": "A1-U1-T08", "t": "pick", "p": "p3", "q": "Woher ___ du?", "a": "kommst", "o": ["komme", "kommt"], "zh": "你从哪里来？", "why": "du 的词尾是 -st。"}, {"id": "A1-U1-T09", "t": "type", "p": "p3", "q": "Wo ___ du?", "hint": "wohnen", "a": "wohnst", "zh": "你住在哪里？", "why": "wohn + st → wohnst。"}, {"id": "A1-U1-T10", "t": "trans", "p": "p3", "src": "Ich komme aus Spanien.", "cue": "换成 er", "q": "Er ___ aus Spanien.", "a": "kommt", "o": ["komme", "kommst"], "zh": "他来自西班牙。", "why": "er/sie 的词尾是 -t。"}, {"id": "A1-U1-T11", "t": "order", "p": "p3", "tiles": ["wohnst", "Wo", "du"], "a": "Wo wohnst du?", "zh": "你住在哪里？", "why": "疑问词第一，动词第二，主语第三。"}, {"id": "A1-U1-T12", "t": "pick", "p": "p3", "q": "___ kommst du? – Aus Deutschland.", "a": "Woher", "o": ["Wo", "Was"], "zh": "你从哪里来？——从德国来。", "why": "回答是 aus …（从……来），问句用 Woher。"}, {"id": "A1-U1-T13", "t": "pick", "p": "p4", "q": "___ du ein Handy?", "a": "Hast", "o": ["Hat", "Habe"], "zh": "你有手机吗？", "why": "du hast；是非问句动词放第一位。"}, {"id": "A1-U1-T14", "t": "fix", "p": "p4", "s": "Das ist keine Problem.", "bad": "keine", "a": "kein", "o": ["keinen", "nicht"], "zh": "这不是问题 / 没问题。", "why": "das Problem 是中性，用 kein。"}, {"id": "A1-U1-T15", "t": "trans", "p": "p4", "src": "Ich habe eine Tasche.", "cue": "改成否定", "q": "Ich habe ___ Tasche.", "a": "keine", "o": ["kein", "nicht"], "zh": "我没有包。", "why": "die Tasche：eine → keine。否定带 ein 的名词用 kein-，不用 nicht。"}]}, "A1-U2": {"title": "联系方式", "intro": "Nico 跟着 Lisa 去生日聚会、听电台、到警察局登记。这一单元你学会了：0–100 和更大的数字、问年龄和电话号码、用 W 问句打听信息，以及说自己从哪里来、住在哪里。", "points": [{"id": "p1", "title": "数字 0–100", "rule": "0–12 要单独记；13–19 是“个位 + zehn”；整十是“个位 + zig”（30 例外：dreißig）；21–99 先说个位，再说 und 和十位，和中文顺序相反。", "table": [["数字", "德语", "规律"], ["13", "dreizehn", "drei + zehn"], ["16", "sechzehn", "sechs 去掉 s"], ["17", "siebzehn", "sieben 去掉 en"], ["20", "zwanzig", ""], ["30", "dreißig", "用 ß，不是 -zig"], ["38", "achtunddreißig", "8 + und + 30"], ["83", "dreiundachtzig", "3 + und + 80"]], "ex": [{"de": "Wie ist die Hausnummer, Emma? 38 oder 83?", "zh": "Emma，门牌号是多少？38 还是 83？"}, {"de": "Das sind 31 Zahlen.", "zh": "一共是 31 个数字。"}], "pit": "21–99 个位在前：38 = achtunddreißig，83 = dreiundachtzig，听的时候最容易搞反。16 是 sechzehn、17 是 siebzehn，都会少几个字母。"}, {"id": "p2", "title": "问年龄和电话号码", "rule": "说年龄用 sein，不用 haben：Ich bin 23 (Jahre alt)。问号码用 Wie ist …?；电话号码可以一个一个数字读，也可以两位一组读，0 读 null。", "table": [["", "熟人（du）", "正式（Sie）"], ["你几岁？", "Wie alt bist du?", "Wie alt sind Sie?"], ["回答", "Ich bin 23 (Jahre alt).", "Ich bin 45."], ["电话号码？", "Wie ist deine Telefonnummer?", "Wie ist Ihre Telefonnummer?"], ["回答", "Meine Telefonnummer ist …", "Meine Nummer ist …"]], "ex": [{"de": "Lotte wird acht Jahre alt.", "zh": "Lotte 要满八岁了。"}, {"de": "Die Telefonnummer ist 0800 – dreimal die Sieben, zweimal die Drei, zweimal die Vier.", "zh": "电话号码是 0800，然后三个 7、两个 3、两个 4。"}], "pit": "“我 23 岁”不能说 Ich habe 23 Jahre（西班牙语、法语习惯会这么说）。打电话时德国人常把 2 读成 zwo，免得和 drei 听混。"}, {"id": "p3", "title": "W 问句 · aus 和 in", "rule": "W 问句：疑问词第一位，动词第二位。问来自哪里用 Woher，回答用 aus；问在哪里用 Wo，回答城市、国家用 in，街道用 in der …straße。", "table": [["疑问词", "问什么", "例句"], ["Wer?", "谁", "Wer ist da?"], ["Was?", "什么", "Was ist das?"], ["Wo?", "在哪里", "Wo ist die Polizei?"], ["Woher?", "从哪里来", "Woher kommst du?"], ["Wie?", "怎么样 / 叫什么", "Wie heißt die Straße?"], ["Warum?", "为什么", "Warum nicht so gut?"], ["Wie viele?", "多少（可数）", "Wie viele Zahlen sind das?"]], "ex": [{"de": "Ich komme aus Spanien. Ich wohne in Sevilla.", "zh": "我来自西班牙。我住在塞维利亚。"}, {"de": "Die Polizei ist in der Schreinerstraße.", "zh": "警察局在 Schreinerstraße。"}], "pit": "少数国名带冠词，aus 后面的冠词要变：aus der Schweiz、aus der Türkei、aus dem Iran、aus den USA。先当固定说法记住，第三格以后会讲。"}, {"id": "p4", "title": "100 以上的数字 · 在机关里问信息", "rule": "百位是“个位 + hundert”，千位是“个位 + tausend”，后面接 100 以内的说法；100 和 1000 常省略 ein。写四位数时，千位后面可以加点：1.000。在警察局等机关要用 Sie。", "table": [["数字", "德语"], ["100", "(ein)hundert"], ["136", "hundertsechsunddreißig"], ["212", "zweihundertzwölf"], ["545", "fünfhundertfünfundvierzig"], ["1000", "(ein)tausend"], ["2025", "zweitausendfünfundzwanzig"]], "ex": [{"de": "Ich wohne in der Wagnergasse 136.", "zh": "我住在 Wagnergasse 136 号。"}, {"de": "Wie ist Ihre Adresse? Welche Nummer haben Sie?", "zh": "您的地址是什么？您的号码是多少？"}], "pit": "整个数字连成一个词，中间不空格：zweihundertzwölf。长号码（电话、证件号）一般一位一位地读。"}], "test": [{"id": "A1-U2-T01", "t": "pick", "p": "p1", "q": "38 = ___", "a": "achtunddreißig", "o": ["dreiundachtzig", "achtunddreizig"], "why": "个位在前：8（acht）+ und + 30（dreißig）。30 用 ß。"}, {"id": "A1-U2-T02", "t": "type", "p": "p1", "say": "siebzehn", "q": "听数字，用阿拉伯数字写出来：___", "a": "17", "why": "siebzehn = 17（sieben 去掉 en + zehn）。"}, {"id": "A1-U2-T03", "t": "fix", "p": "p1", "s": "Das sind einunddreisig Zahlen.", "bad": "einunddreisig", "a": "einunddreißig", "o": ["dreiundeinzig", "einsunddreißig"], "zh": "一共是 31 个数字。", "why": "30 是 dreißig（ß）；31 = einunddreißig，eins 在组合里写成 ein。"}, {"id": "A1-U2-T04", "t": "pick", "p": "p1", "q": "16 = ___", "a": "sechzehn", "o": ["sechszehn", "sechzig"], "why": "16 写作 sechzehn，sechs 的 s 去掉；sechzig 是 60。"}, {"id": "A1-U2-T05", "t": "pick", "p": "p2", "q": "Wie alt ___ du? – Ich bin 23.", "a": "bist", "o": ["hast", "bin"], "zh": "你几岁？——我 23 岁。", "why": "问年龄用 sein：du bist。"}, {"id": "A1-U2-T06", "t": "fix", "p": "p2", "s": "Ich habe 23 Jahre alt.", "bad": "habe", "a": "bin", "o": ["hast", "ist"], "zh": "我 23 岁。", "why": "德语说年龄用 sein：Ich bin 23 Jahre alt。"}, {"id": "A1-U2-T07", "t": "trans", "p": "p2", "src": "Wie ist deine Telefonnummer?", "cue": "对 Herr Brunner 说（正式）", "q": "Wie ist ___ Telefonnummer?", "a": "Ihre", "o": ["deine", "Ihr"], "zh": "您的电话号码是多少？", "why": "正式场合用 Ihre；die Telefonnummer 是阴性，所以是 Ihre，不是 Ihr。"}, {"id": "A1-U2-T08", "t": "type", "p": "p2", "say": "null, acht, null, null", "q": "听号码，写出数字：___", "a": "0800", "alt": ["0 8 0 0"], "why": "null = 0，号码一位一位地读。"}, {"id": "A1-U2-T09", "t": "pick", "p": "p3", "q": "___ ist die Polizei? – In der Schreinerstraße.", "a": "Wo", "o": ["Woher", "Wer"], "zh": "警察局在哪里？——在 Schreinerstraße。", "why": "问“在哪里”用 Wo。"}, {"id": "A1-U2-T10", "t": "pick", "p": "p3", "q": "Ich komme ___ Spanien.", "a": "aus", "o": ["in", "von"], "zh": "我来自西班牙。", "why": "来自某个国家或城市：kommen aus …。"}, {"id": "A1-U2-T11", "t": "order", "p": "p3", "tiles": ["heißt", "Wie", "Straße", "die"], "a": "Wie heißt die Straße?", "zh": "这条街叫什么？", "why": "疑问词 Wie 第一，动词 heißt 第二。"}, {"id": "A1-U2-T12", "t": "pick", "p": "p3", "q": "Ich komme aus ___ Schweiz.", "a": "der", "o": ["die", "dem"], "zh": "我来自瑞士。", "why": "die Schweiz 带冠词，跟在 aus 后面变成 der：aus der Schweiz。先当固定说法记住。"}, {"id": "A1-U2-T13", "t": "pick", "p": "p4", "q": "212 = ___", "a": "zweihundertzwölf", "o": ["zweihundertzwanzig", "zwölfhundertzwei"], "why": "先说百位 zweihundert，再说 12（zwölf），连成一个词。"}, {"id": "A1-U2-T14", "t": "type", "p": "p4", "say": "dreihundertdreiundzwanzig", "q": "听数字，用阿拉伯数字写出来：___", "a": "323", "why": "dreihundert（300）+ dreiundzwanzig（23）= 323。"}, {"id": "A1-U2-T15", "t": "pick", "p": "p4", "q": "Lisa wohnt in der Wagnergasse 136：136 = ___", "a": "hundertsechsunddreißig", "o": ["hundertdreiundsechzig", "sechsunddreißighundert"], "zh": "Lisa 住在 Wagnergasse 136 号。", "why": "hundert + sechsunddreißig（6 + und + 30）。也可以说 einhundertsechsunddreißig。"}]}, "A1-U3": {"title": "社交圈", "intro": "Nico 住进了 Lisa 的合租公寓，认识了 Sebastian、Nina 和 Nawin，一起点饮料、叫比萨、付账。这一单元你学会了：名词的性和 wer / was、用 möchten 点东西、e → i 换音的动词，以及问价格和付钱。", "points": [{"id": "p1", "title": "名词的性 · wer 和 was", "rule": "名词的性要跟冠词一起记；饮料、食物也不例外。问人用 wer，问东西用 was。", "table": [["阳性 der", "阴性 die", "中性 das"], ["der Kaffee", "die Milch", "das Wasser"], ["der Tee", "die Cola", "das Bier"], ["der Saft", "die Limonade", "das Eis"], ["der Wein", "die Pizza", "das Sushi"]], "ex": [{"de": "Wer ist denn das? – Das ist Nico.", "zh": "这是谁呀？——这是 Nico。"}, {"de": "Was ist das? – Das ist ein Kühlschrank.", "zh": "这是什么？——这是冰箱。"}], "pit": "复合词看最后一个词：der Apfel + der Saft = der Apfelsaft；die Orange + der Saft = der Orangensaft。"}, {"id": "p2", "title": "möchten · es gibt", "rule": "想要什么用 möchten，后面直接接东西，或者接动词原形放句尾。问“有什么”用 Was gibt es?，回答 Es gibt … 。", "table": [["人称", "möchten"], ["ich", "möchte"], ["du", "möchtest"], ["er / sie", "möchte"], ["wir", "möchten"], ["ihr", "möchtet"], ["sie / Sie", "möchten"]], "ex": [{"de": "Was möchtest du trinken? – Eine Cola, bitte.", "zh": "你想喝什么？——请给我一杯可乐。"}, {"de": "Was gibt es denn? – Sushi, Pizza, Salat.", "zh": "有什么呢？——寿司、比萨、沙拉。"}], "pit": "er / sie 的形式是 möchte，和 ich 一样，没有 -t：Nina möchte einen Tee。ihr 是对两个以上熟人说“你们”：Was möchtet ihr?"}, {"id": "p3", "title": "换音动词：e → i", "rule": "essen、nehmen 这类动词，在 du 和 er / sie 的时候词干的 e 变成 i，其他人称照常变化。nehmen 变化特别：du nimmst、er nimmt。", "table": [["人称", "essen", "nehmen"], ["ich", "esse", "nehme"], ["du", "isst", "nimmst"], ["er / sie", "isst", "nimmt"], ["wir", "essen", "nehmen"], ["ihr", "esst", "nehmt"], ["sie / Sie", "essen", "nehmen"]], "ex": [{"de": "Ich esse gern Pizza mit Salami. Und was isst du gern?", "zh": "我喜欢吃萨拉米比萨。你喜欢吃什么？"}, {"de": "Ich nehme eine Pizza mit Thunfisch. Und was nimmst du?", "zh": "我要金枪鱼比萨。你要什么？"}], "pit": "du isst 只写两个 s（不是 issst）；ihr esst 不换音。"}, {"id": "p4", "title": "问价格 · 付钱", "rule": "问价格用 Was kostet …? 或 Wie viel kostet …?；结账时说 Das macht (zusammen) … Euro。价格读作“几欧元 + 几分”：22,50 € = zweiundzwanzig Euro fünfzig。", "table": [["场景", "说法"], ["多少钱？", "Was kostet das? / Wie viel kostet die Pizza?"], ["一共", "Das macht zusammen 40,50 Euro."], ["一起还是分开付？", "Zahlen Sie zusammen oder getrennt?"], ["现金还是刷卡？", "Zahlen Sie bar oder mit Karte?"], ["不用找了", "Das stimmt so."]], "ex": [{"de": "Die drei Pizzen mit Salami sind 22,50.", "zh": "三个萨拉米比萨一共 22.50 欧元。"}, {"de": "Ich zahle bar. Hier sind 45 Euro. Das stimmt so.", "zh": "我付现金。这是 45 欧元，不用找了。"}], "pit": "价格里 Euro 不加复数：45 Euro（不是 45 Euros）。德语用逗号表示小数：40,50 €。"}], "test": [{"id": "A1-U3-T01", "t": "pick", "p": "p1", "q": "___ ist das? – Das ist Sebastian.", "a": "Wer", "o": ["Was", "Wo"], "why": "问人用 wer。", "zh": "这是谁？——这是 Sebastian。"}, {"id": "A1-U3-T02", "t": "pick", "p": "p1", "q": "___ ist das? – Das ist ein Kühlschrank.", "a": "Was", "o": ["Wer", "Wie"], "why": "问东西用 was。", "zh": "这是什么？——这是冰箱。"}, {"id": "A1-U3-T03", "t": "sort", "p": "p1", "q": "饮料按冠词分类", "cats": ["der", "die", "das"], "items": [{"w": "Tee", "c": 0}, {"w": "Orangensaft", "c": 0}, {"w": "Milch", "c": 1}, {"w": "Limonade", "c": 1}, {"w": "Wasser", "c": 2}, {"w": "Bier", "c": 2}], "why": "der Tee、der Orangensaft · die Milch、die Limonade · das Wasser、das Bier"}, {"id": "A1-U3-T04", "t": "fix", "p": "p1", "s": "Die Kaffee ist heiß.", "bad": "Die", "a": "Der", "o": ["Das", "Den"], "why": "der Kaffee 是阳性。", "zh": "咖啡很烫。"}, {"id": "A1-U3-T05", "t": "pick", "p": "p2", "q": "Nina ___ einen Tee.", "a": "möchte", "o": ["möchtet", "möchtest"], "why": "er / sie 用 möchte，没有 -t。", "zh": "Nina 想要一杯茶。"}, {"id": "A1-U3-T06", "t": "type", "p": "p2", "q": "Was ___ du trinken?", "a": "möchtest", "why": "du 的词尾是 -st：möchtest。", "hint": "möchten", "zh": "你想喝什么？"}, {"id": "A1-U3-T07", "t": "trans", "p": "p2", "src": "Was möchtest du essen?", "cue": "问 Nina 和 Sebastian 两个人（ihr）", "q": "Was ___ ihr essen?", "a": "möchtet", "o": ["möchten", "möchtest"], "why": "对两个以上熟人说“你们”用 ihr：ihr möchtet。", "zh": "你们想吃什么？"}, {"id": "A1-U3-T08", "t": "order", "p": "p2", "tiles": ["es", "Was", "denn", "gibt"], "a": "Was gibt es denn?", "zh": "有什么呢？", "why": "W 问句：疑问词第一，动词 gibt 第二。denn 让问句更口语、更自然。"}, {"id": "A1-U3-T09", "t": "pick", "p": "p3", "q": "Was ___ du gern, Nina?", "a": "isst", "o": ["esst", "essest"], "why": "essen 换音：du isst。", "zh": "Nina，你喜欢吃什么？"}, {"id": "A1-U3-T10", "t": "pick", "p": "p3", "q": "Nico ___ eine Pizza mit Salami.", "a": "nimmt", "o": ["nehmt", "nimmst"], "why": "nehmen：er / sie nimmt。", "zh": "Nico 要一个萨拉米比萨。"}, {"id": "A1-U3-T11", "t": "fix", "p": "p3", "s": "Du nehmst die Pizza Hawaii.", "bad": "nehmst", "a": "nimmst", "o": ["nimmt", "nehmt"], "why": "nehmen 在 du 的时候变成 nimmst。", "zh": "你要夏威夷比萨。"}, {"id": "A1-U3-T12", "t": "type", "p": "p3", "q": "Ich ___ gern Sushi.", "a": "esse", "why": "ich 不换音：ich esse。", "hint": "essen", "zh": "我喜欢吃寿司。"}, {"id": "A1-U3-T13", "t": "pick", "p": "p4", "q": "___ kostet die Pizza? – Zehn Euro.", "a": "Was", "o": ["Wer", "Wie viele"], "why": "问价格：Was kostet …?（也可以说 Wie viel kostet …?，但不是 Wie viele）", "zh": "比萨多少钱？——十欧元。"}, {"id": "A1-U3-T14", "t": "pick", "p": "p4", "q": "40,50 € = vierzig Euro ___", "a": "fünfzig", "o": ["fünfzehn", "fünf"], "why": "价格读作“几欧元 + 几分”：40,50 € = vierzig Euro fünfzig。"}, {"id": "A1-U3-T15", "t": "pick", "p": "p4", "q": "Zahlen Sie zusammen oder ___?", "a": "getrennt", "o": ["bar", "Karte"], "why": "一起付还是分开付：zusammen oder getrennt。", "zh": "您要一起付还是分开付？"}]}, "A1-U4": {"title": "国家和语言", "intro": "Nawin 的告别派对上，大家聊去过的城市、各国的美食和会说的语言，Nico 还认识了 Selma。这一单元你学会了：sein 的过去时 war、in / nach / aus 和东南西北、德语的三种基本语序，以及 man 和 sprechen。", "points": [{"id": "p1", "title": "sein 的过去时：war", "rule": "说“去过 / 当时是”，口语里常用 sein 的过去时。搭配 schon mal（曾经）和 noch nie（从没）。", "table": [["人称", "现在时", "过去时"], ["ich", "bin", "war"], ["du", "bist", "warst"], ["er / sie", "ist", "war"], ["wir", "sind", "waren"], ["ihr", "seid", "wart"], ["sie / Sie", "sind", "waren"]], "ex": [{"de": "Warst du schon mal in Köln? – Nein, ich war noch nie in Köln.", "zh": "你去过科隆吗？——没有，我从没去过科隆。"}, {"de": "Die Party war super!", "zh": "派对太棒了！"}], "pit": "ich 和 er / sie 都是 war；wir 和 sie / Sie 都是 waren。"}, {"id": "p2", "title": "in · nach · aus · 东南西北", "rule": "Wo?（在哪）→ in + 城市 / 国家；Wohin?（去哪）→ nach + 城市 / 国家；Woher?（从哪来）→ aus。方位：im Norden / Süden / Osten / Westen (von …)。", "table": [["问", "回答", "例子"], ["Wo?", "in + 城市 / 国家", "Der Dom ist in Köln."], ["Wohin?", "nach + 城市 / 国家", "Ich fahre nach München."], ["Woher?", "aus + 城市 / 国家", "Selma kommt aus Syrien."], ["在哪一边？", "im Süden von …", "Sevilla ist im Süden von Spanien."]], "ex": [{"de": "Nächste Woche fahre ich nach München.", "zh": "下周我去慕尼黑。"}, {"de": "Spanien ist im Süden von Europa.", "zh": "西班牙在欧洲南部。"}], "pit": "带冠词的国名去往时不用 nach：in die Schweiz、in die USA（以后会细讲）。"}, {"id": "p3", "title": "三种基本语序", "rule": "陈述句：变位动词在第二位，第一位可以是主语，也可以是时间、地点；是非问句：动词在第一位；W 问句：疑问词第一，动词第二。", "table": [["句型", "第 1 位", "第 2 位", "后面"], ["陈述句", "Ich", "komme", "aus Spanien."], ["陈述句（倒装）", "In Frankreich", "isst", "man gern Käse."], ["W 问句", "Woher", "kommst", "du?"], ["是非问句", "Kommst", "du", "aus Italien?"]], "ex": [{"de": "Kommst du aus Italien? – Nein, ich komme aus Spanien.", "zh": "你来自意大利吗？——不，我来自西班牙。"}, {"de": "Nächstes Jahr fahre ich nach Norwegen.", "zh": "明年我去挪威。"}], "pit": "时间或地点放在句首时，动词仍然排第二，主语挪到动词后面：Nächstes Jahr fahre ich …（不是 Nächstes Jahr ich fahre）。"}, {"id": "p4", "title": "man · sprechen", "rule": "man 指“人们 / 大家”，动词用 er / sie 的形式。sprechen 也是 e → i 的换音动词：du sprichst、er spricht。语言名称前不加冠词。", "table": [["人称", "sprechen"], ["ich", "spreche"], ["du", "sprichst"], ["er / sie / man", "spricht"], ["wir", "sprechen"], ["ihr", "sprecht"], ["sie / Sie", "sprechen"]], "ex": [{"de": "In Spanien isst man Gazpacho.", "zh": "在西班牙人们吃西班牙冷汤。"}, {"de": "Ich spreche Spanisch, ein bisschen Englisch und ein bisschen Deutsch.", "zh": "我说西班牙语，还会一点英语和一点德语。"}], "pit": "man（人们）只有一个 n、小写；der Mann（男人）两个 n、大写。"}], "test": [{"id": "A1-U4-T01", "t": "pick", "p": "p1", "q": "___ du schon mal in Köln?", "a": "Warst", "o": ["Wart", "War"], "why": "du warst。", "zh": "你去过科隆吗？"}, {"id": "A1-U4-T02", "t": "pick", "p": "p1", "q": "Ich ___ noch nie in Heidelberg.", "a": "war", "o": ["warst", "waren"], "why": "ich war。", "zh": "我从没去过海德堡。"}, {"id": "A1-U4-T03", "t": "type", "p": "p1", "q": "Die Party ___ super!", "a": "war", "why": "die Party 是单数：war。", "hint": "sein 的过去时", "zh": "派对太棒了！"}, {"id": "A1-U4-T04", "t": "fix", "p": "p1", "s": "Wir war schon mal in Hamburg.", "bad": "war", "a": "waren", "o": ["wart", "warst"], "why": "wir waren。", "zh": "我们去过汉堡。"}, {"id": "A1-U4-T05", "t": "pick", "p": "p2", "q": "Nächste Woche fahre ich ___ München.", "a": "nach", "o": ["in", "aus"], "why": "去往城市：nach + 城市。", "zh": "下周我去慕尼黑。"}, {"id": "A1-U4-T06", "t": "pick", "p": "p2", "q": "Die Semperoper ist ___ Dresden.", "a": "in", "o": ["nach", "aus"], "why": "在某个城市：in + 城市。", "zh": "森帕歌剧院在德累斯顿。"}, {"id": "A1-U4-T07", "t": "pick", "p": "p2", "q": "Sevilla liegt im ___ von Spanien.", "a": "Süden", "o": ["Süd", "südlich"], "why": "im Süden von …：在……的南部。", "zh": "塞维利亚位于西班牙南部。"}, {"id": "A1-U4-T08", "t": "order", "p": "p3", "tiles": ["fahre", "Woche", "nach", "Nächste", "ich", "München"], "a": "Nächste Woche fahre ich nach München.", "zh": "下周我去慕尼黑。", "why": "动词 fahre 在第二位；时间放句首时，主语 ich 挪到动词后面。", "alt": ["Ich fahre nächste Woche nach München.", "Nach München fahre ich nächste Woche."]}, {"id": "A1-U4-T09", "t": "pick", "p": "p3", "q": "哪一句语序正确？___", "a": "In Frankreich isst man gern Käse.", "o": ["In Frankreich man isst gern Käse.", "In Frankreich gern isst man Käse."], "why": "地点 In Frankreich 占第一位，动词 isst 必须紧跟在第二位。"}, {"id": "A1-U4-T10", "t": "trans", "p": "p3", "src": "Du kommst aus Italien.", "cue": "改成是非问句", "q": "___ du aus Italien?", "a": "Kommst", "o": ["Kommt", "Komme"], "why": "是非问句：变位动词放第一位，主语跟在后面。", "zh": "你来自意大利吗？"}, {"id": "A1-U4-T11", "t": "pick", "p": "p4", "q": "In Spanien ___ man Gazpacho.", "a": "isst", "o": ["essen", "esst"], "why": "man 的动词用 er / sie 的形式：man isst。", "zh": "在西班牙人们吃西班牙冷汤。"}, {"id": "A1-U4-T12", "t": "pick", "p": "p4", "q": "Welche Sprachen ___ du, Nico?", "a": "sprichst", "o": ["sprechst", "spricht"], "why": "sprechen 换音：du sprichst。", "zh": "Nico，你会说哪些语言？"}, {"id": "A1-U4-T13", "t": "fix", "p": "p4", "s": "Lisa sprecht Deutsch, Englisch und Italienisch.", "bad": "sprecht", "a": "spricht", "o": ["sprichst", "spreche"], "why": "er / sie 用 spricht；sprecht 是 ihr 的形式。", "zh": "Lisa 说德语、英语和意大利语。"}, {"id": "A1-U4-T14", "t": "pick", "p": "p4", "q": "Herr Müller ist ein ___.", "a": "Mann", "o": ["man", "Man"], "why": "“男人”是名词 der Mann（大写、两个 n）；man 是“人们”。", "zh": "Müller 先生是个男人。"}, {"id": "A1-U4-T15", "t": "type", "p": "p4", "q": "In Österreich ___ man Deutsch.", "a": "spricht", "why": "man + er / sie 的形式：man spricht。", "hint": "sprechen", "zh": "在奥地利人们说德语。"}]}, "A1-U5": {"title": "物品", "intro": "Nico 在合租公寓的第一天，跟着 Lisa 去语言学校，又一起去找 Yara 的店。这一单元你学会了：定冠词和复数、不定冠词、主语和宾语（第一格、第四格），以及 sein + 形容词。", "points": [{"id": "p1", "title": "定冠词与复数", "rule": "谈论双方都知道的那一个时用定冠词 der / die / das。所有名词的复数，定冠词一律是 die。复数形式要跟单数一起记。", "table": [["", "单数", "复数"], ["阳性", "der Stift", "die Stifte"], ["阴性", "die Brille", "die Brillen"], ["中性", "das Buch", "die Bücher"], ["中性", "das Wort", "die Wörter"]], "ex": [{"de": "Wo ist die Brille? – Die Brille ist hier.", "zh": "眼镜在哪儿？——眼镜在这儿。"}, {"de": "Wo sind die Stifte? – Die Stifte sind hier.", "zh": "笔在哪儿？——笔在这儿。"}], "pit": "复数常见变化：加 -e（Stifte）、加 -n / -en（Brillen）、加 -er 并变音（Bücher）。der Schlüssel 的复数还是 die Schlüssel。"}, {"id": "p2", "title": "不定冠词 ein / eine", "rule": "第一次提到、不特指的东西用 ein / eine；特指（说过的、属于谁的）用 der / die / das。复数不特指时不加冠词。", "table": [["", "定冠词", "不定冠词"], ["阳性", "der Stift", "ein Stift"], ["阴性", "die Brille", "eine Brille"], ["中性", "das Buch", "ein Buch"], ["复数", "die Bücher", "Bücher"]], "ex": [{"de": "Das ist eine Tasche.", "zh": "这是一个包。"}, {"de": "Und das ist die Tasche von Jenny.", "zh": "这是 Jenny 的那个包。"}], "pit": "没有“ein + 复数”：Das sind Stifte（不是 eine Stifte）。"}, {"id": "p3", "title": "主语和宾语：第一格、第四格", "rule": "主语用第一格；很多动词（haben、brauchen、suchen、nehmen、essen …）后面的宾语用第四格。第四格只有阳性会变：der → den，ein → einen，kein → keinen。", "table": [["", "第一格（主语）", "第四格（宾语）"], ["阳性", "der / ein / kein Stift", "den / einen / keinen Stift"], ["阴性", "die / eine / keine Tasche", "die / eine / keine Tasche"], ["中性", "das / ein / kein Buch", "das / ein / kein Buch"], ["复数", "die / – / keine Stifte", "die / – / keine Stifte"]], "ex": [{"de": "Hast du einen Stift? – Nein, ich habe keinen Stift.", "zh": "你有笔吗？——没有，我没有笔。"}, {"de": "Wir suchen einen Mieter für Nawins Zimmer.", "zh": "我们在给 Nawin 的房间找租客。"}], "pit": "先看名词是不是阳性，再看它在句子里是不是宾语。阴性、中性、复数的第四格和第一格一样。"}, {"id": "p4", "title": "sein + 形容词", "rule": "形容词放在 sein 后面描述人和东西，这时形容词保持原形、小写、不加词尾。形容词最好和反义词一起记。", "table": [["形容词", "反义词"], ["groß 大", "klein 小"], ["alt 老、旧", "neu 新"], ["teuer 贵", "billig 便宜"], ["颜色", "rot、gelb、weiß"]], "ex": [{"de": "Das Auto ist rot, aber es ist nicht groß, es ist klein.", "zh": "这辆车是红色的，但不大，是小的。"}, {"de": "Das Haus ist groß und gelb.", "zh": "这栋房子又大又黄。"}], "pit": "sein 后面的形容词不加词尾：Das Haus ist alt（不是 altes）。形容词不大写。"}], "test": [{"id": "A1-U5-T01", "t": "pick", "p": "p1", "q": "Wo ist ___ Brille?", "a": "die", "o": ["der", "das"], "why": "die Brille 是阴性。", "zh": "眼镜在哪儿？"}, {"id": "A1-U5-T02", "t": "pick", "p": "p1", "q": "Wo sind ___ Stifte?", "a": "die", "o": ["der", "das"], "why": "复数的定冠词一律是 die。", "zh": "笔在哪儿？"}, {"id": "A1-U5-T03", "t": "sort", "p": "p1", "q": "单数还是复数？", "cats": ["单数", "复数"], "items": [{"w": "Buch", "c": 0}, {"w": "Tafel", "c": 0}, {"w": "Stift", "c": 0}, {"w": "Bücher", "c": 1}, {"w": "Stifte", "c": 1}, {"w": "Brillen", "c": 1}], "why": "Buch → Bücher，Stift → Stifte，Brille → Brillen。"}, {"id": "A1-U5-T04", "t": "type", "p": "p1", "q": "das Buch → die ___", "a": "Bücher", "why": "复数加 -er 并变音：Buch → Bücher。", "hint": "复数"}, {"id": "A1-U5-T05", "t": "pick", "p": "p2", "q": "Was ist das? – Das ist ___ Stift.", "a": "ein", "o": ["eine", "einen"], "why": "der Stift，不特指 → ein Stift。", "zh": "这是什么？——这是一支笔。"}, {"id": "A1-U5-T06", "t": "pick", "p": "p2", "q": "复数、不特指时：Das sind ___.", "a": "Stifte", "o": ["eine Stifte", "ein Stifte"], "why": "复数不加不定冠词。", "zh": "这些是笔。"}, {"id": "A1-U5-T07", "t": "fix", "p": "p2", "s": "Das ist ein Brille.", "bad": "ein", "a": "eine", "o": ["einen", "einer"], "why": "die Brille 是阴性 → eine Brille。", "zh": "这是一副眼镜。"}, {"id": "A1-U5-T08", "t": "pick", "p": "p3", "q": "Hast du ___ Stift?", "a": "einen", "o": ["ein", "eine"], "why": "der Stift 在这里是宾语（第四格）→ einen。", "zh": "你有笔吗？"}, {"id": "A1-U5-T09", "t": "pick", "p": "p3", "q": "Nein, ich habe ___ Stift.", "a": "keinen", "o": ["kein", "keine"], "why": "阳性宾语：kein → keinen。", "zh": "没有，我没有笔。"}, {"id": "A1-U5-T10", "t": "fix", "p": "p3", "s": "Ich brauche ein Zettel.", "bad": "ein", "a": "einen", "o": ["eine", "einem"], "why": "der Zettel 是宾语 → einen Zettel。", "zh": "我需要一张纸条。"}, {"id": "A1-U5-T11", "t": "sort", "p": "p3", "q": "第一格还是第四格？", "cats": ["第一格（主语）", "第四格（宾语）"], "items": [{"w": "der Zettel", "c": 0}, {"w": "ein Mieter", "c": 0}, {"w": "kein Aufzug", "c": 0}, {"w": "den Zettel", "c": 1}, {"w": "einen Mieter", "c": 1}, {"w": "keinen Aufzug", "c": 1}], "why": "阳性第四格：der → den，ein → einen，kein → keinen。"}, {"id": "A1-U5-T12", "t": "pick", "p": "p4", "q": "groß ↔ ___", "a": "klein", "o": ["alt", "rot"], "why": "groß 的反义词是 klein。"}, {"id": "A1-U5-T13", "t": "fix", "p": "p4", "s": "Das Haus ist Gelb.", "bad": "Gelb", "a": "gelb", "o": ["Gelbe", "gelbes"], "why": "形容词小写，在 sein 后面不加词尾。", "zh": "这栋房子是黄色的。"}, {"id": "A1-U5-T14", "t": "pick", "p": "p4", "q": "billig ↔ ___", "a": "teuer", "o": ["neu", "weiß"], "why": "billig 的反义词是 teuer。"}, {"id": "A1-U5-T15", "t": "type", "p": "p4", "q": "Das Fahrrad ist ___.", "a": "neu", "why": "sein + 形容词原形。", "hint": "新的", "zh": "这辆自行车是新的。"}]}, "A1-U6": {"title": "居住", "intro": "合租公寓的暖气坏了，Nico 得另找地方住；几位看房的人轮流上门。这一单元你学会了：冠词总表（第一格、第四格）、用 nicht 否定形容词、zu + 形容词和复合词，以及物主冠词 mein / dein / sein / ihr …", "points": [{"id": "p1", "title": "冠词总表：定冠词、不定冠词、否定冠词", "rule": "特指用 der / die / das，不特指用 ein / eine，否定名词用 kein / keine。做宾语（第四格）时只有阳性会变。", "table": [["", "第一格", "第四格"], ["阳性", "der / ein / kein", "den / einen / keinen"], ["阴性", "die / eine / keine", "die / eine / keine"], ["中性", "das / ein / kein", "das / ein / kein"], ["复数", "die / – / keine", "die / – / keine"]], "ex": [{"de": "Ist das ein Fahrrad? – Nein, das ist kein Fahrrad. Das ist ein Auto.", "zh": "这是自行车吗？——不，这不是自行车，是汽车。"}, {"de": "Das ist das Auto von Lisa.", "zh": "这是 Lisa 的车。"}], "pit": "es gibt、haben、suchen、brauchen 后面都是第四格：Hier gibt es keinen Garten。"}, {"id": "p2", "title": "nicht 还是 kein", "rule": "否定形容词用 nicht，放在形容词前面；否定带 ein 或不带冠词的名词用 kein。", "table": [["否定什么", "用什么", "例子"], ["形容词", "nicht", "Das Zimmer ist nicht groß."], ["ein + 名词", "kein", "Das ist kein Problem."], ["没有冠词的名词", "kein", "Hier ist keine Toilette."]], "ex": [{"de": "Das Zimmer ist klein. Das Zimmer ist nicht groß.", "zh": "房间很小。房间不大。"}, {"de": "Das Bad ist dunkel. Es ist nicht hell.", "zh": "浴室很暗，不亮。"}], "pit": "nicht 不能直接放在名词前代替 kein：Das ist kein Problem（不是 nicht Problem）。"}, {"id": "p3", "title": "zu + 形容词 · 复合词", "rule": "zu + 形容词表示“太……（不合适）”。复合词由几个名词组成，冠词跟最后一个词走。", "table": [["复合词", "组成", "冠词"], ["der Kleiderschrank", "die Kleider + der Schrank", "der"], ["der Küchenschrank", "die Küche + der Schrank", "der"], ["das Badezimmer", "das Bad + das Zimmer", "das"], ["das Bücherregal", "die Bücher + das Regal", "das"]], "ex": [{"de": "Der Schrank ist viel zu groß.", "zh": "这个柜子太大了。"}, {"de": "Das Haus ist schön, aber es ist zu teuer.", "zh": "房子很漂亮，可是太贵了。"}], "pit": "zu groß = 太大（不合适）；sehr groß = 很大（只是描述）。"}, {"id": "p4", "title": "物主冠词 mein / dein / sein / ihr …", "rule": "表示“谁的”用物主冠词。跟在阴性和复数名词前加 -e。sein 指男性的，ihr 指女性的。", "table": [["人称", "物主冠词", "例子"], ["ich", "mein(e)", "mein Föhn / meine Brille"], ["du", "dein(e)", "dein Zimmer / deine Uhr"], ["er", "sein(e)", "Nico → sein Pass"], ["sie", "ihr(e)", "Lisa → ihre Brille"], ["wir", "unser(e)", "unser Bad"], ["ihr", "euer / eure", "euer Bad / eure Küche"], ["Sie", "Ihr(e)", "Ihr Zimmer"]], "ex": [{"de": "Nawin, ist das deine Unterhose? – Nein, das ist meine.", "zh": "Nawin，这是你的内裤吗？——不，是我的。"}, {"de": "Wir haben nur ein Bad.", "zh": "我们只有一个浴室。"}], "pit": "看“东西是谁的”：属于男人用 sein，属于女人用 ihr；再看名词的性决定加不加 -e。"}], "test": [{"id": "A1-U6-T01", "t": "pick", "p": "p1", "q": "Ist das ein Fahrrad? – Nein, das ist ___ Fahrrad.", "a": "kein", "o": ["nicht", "keine"], "why": "否定带 ein 的名词用 kein；das Fahrrad → kein。", "zh": "这是自行车吗？——不，这不是自行车。"}, {"id": "A1-U6-T02", "t": "pick", "p": "p1", "q": "Nawin isst ___ Apfel.（一个）", "a": "einen", "o": ["ein", "eine"], "why": "der Apfel 是宾语 → einen。", "zh": "Nawin 在吃一个苹果。"}, {"id": "A1-U6-T03", "t": "fix", "p": "p1", "s": "Ich suche der Schlüssel.", "bad": "der", "a": "den", "o": ["dem", "die"], "why": "der Schlüssel 是宾语 → den。", "zh": "我在找钥匙。"}, {"id": "A1-U6-T04", "t": "trans", "p": "p1", "src": "Wir haben einen Balkon.", "cue": "改成否定", "q": "Wir haben ___ Balkon.", "a": "keinen", "o": ["kein", "nicht"], "why": "阳性宾语：einen → keinen。", "zh": "我们没有阳台。"}, {"id": "A1-U6-T05", "t": "pick", "p": "p2", "q": "Das Zimmer ist ___ groß, es ist klein.", "a": "nicht", "o": ["kein", "keine"], "why": "否定形容词用 nicht。", "zh": "房间不大，是小的。"}, {"id": "A1-U6-T06", "t": "order", "p": "p2", "tiles": ["nicht", "Das", "hell", "ist", "Zimmer"], "a": "Das Zimmer ist nicht hell.", "zh": "房间不亮。", "why": "nicht 放在形容词前面。"}, {"id": "A1-U6-T07", "t": "pick", "p": "p2", "q": "Das ist ___ Problem.（否定）", "a": "kein", "o": ["nicht", "keine"], "why": "否定名词用 kein：kein Problem。", "zh": "这不是问题。"}, {"id": "A1-U6-T08", "t": "pick", "p": "p3", "q": "（太大了，不合适）Der Schrank ist ___ groß.", "a": "zu", "o": ["sehr", "viel"], "why": "zu + 形容词 = 太……；sehr 只是“很”。", "zh": "这个柜子太大了。"}, {"id": "A1-U6-T09", "t": "pick", "p": "p3", "q": "der Spiegel + der Schrank → ___ Spiegelschrank", "a": "der", "o": ["die", "das"], "why": "复合词的冠词看最后一个词：der Schrank。", "zh": "镜柜"}, {"id": "A1-U6-T10", "t": "type", "p": "p3", "q": "die Küche + der Schrank → der ___", "a": "Küchenschrank", "why": "Küche 加 -n 再接 Schrank：der Küchenschrank。", "hint": "复合词"}, {"id": "A1-U6-T11", "t": "pick", "p": "p3", "q": "Die Wohnung ist zu ___. Ich kann die Miete nicht bezahlen.", "a": "teuer", "o": ["billig", "klein"], "why": "付不起房租 → 太贵：zu teuer。", "zh": "公寓太贵了，我付不起房租。"}, {"id": "A1-U6-T12", "t": "pick", "p": "p4", "q": "Sebastian: Das ist ___ Unterhose.（我的）", "a": "meine", "o": ["mein", "meinen"], "why": "die Unterhose 是阴性 → meine。", "zh": "这是我的内裤。"}, {"id": "A1-U6-T13", "t": "pick", "p": "p4", "q": "Ist das Lisas Föhn? – Ja, das ist ___ Föhn.", "a": "ihr", "o": ["sein", "ihre"], "why": "Lisa 是女性 → ihr；der Föhn 是阳性，不加 -e。", "zh": "这是 Lisa 的吹风机吗？——是，是她的吹风机。"}, {"id": "A1-U6-T14", "t": "fix", "p": "p4", "s": "Nawin, ist das deine Zimmer?", "bad": "deine", "a": "dein", "o": ["deinen", "meine"], "why": "das Zimmer 是中性 → dein。", "zh": "Nawin，这是你的房间吗？"}, {"id": "A1-U6-T15", "t": "trans", "p": "p4", "src": "Das ist mein Zimmer.", "cue": "换成“我们的”", "q": "Das ist ___ Zimmer.", "a": "unser", "o": ["unsere", "euer"], "why": "wir → unser；das Zimmer 不加 -e。", "zh": "这是我们的房间。"}]}, "A1-U7": {"title": "日期与时间", "intro": "Lisa 要上课，Nico 替她照看 Emma 一整天。这一单元你学会了：日常说时间和 halb、时间介词 um / von … bis / am、可分动词和频率副词，以及 zuerst / dann / danach 和 a → ä 换音。", "points": [{"id": "p1", "title": "日常说时间", "rule": "日常用 12 小时制：Es ist acht (Uhr)。需要区分时补上 morgens、mittags、nachmittags、abends。半点说“下一个整点的一半”：7:30 = halb acht。", "table": [["时间", "说法"], ["8:00", "Es ist acht (Uhr)."], ["20:00", "Es ist acht Uhr abends."], ["12:00", "Es ist zwölf Uhr mittags."], ["7:30", "Es ist halb acht."], ["14:30", "Es ist halb drei."]], "ex": [{"de": "Emma steht um halb sieben auf.", "zh": "Emma 六点半起床。"}, {"de": "Wie spät ist es? – Es ist zwölf.", "zh": "几点了？——十二点。"}], "pit": "halb 后面是下一个整点：halb acht 是 7:30，不是 8:30。"}, {"id": "p2", "title": "时间介词 um · von … bis · am", "rule": "具体时刻用 um；一段时间用 von … bis；星期几用 am（an + dem）。问时间用 Wann?", "table": [["问", "介词", "例子"], ["几点？", "um", "Der Kurs beginnt um neun."], ["从几点到几点？", "von … bis", "Ich arbeite von acht bis zwölf."], ["星期几？", "am", "Am Freitag sieht Emma fern."]], "ex": [{"de": "Wann beginnt der Kurs? – Um neun.", "zh": "课几点开始？——九点。"}, {"de": "Am Mittwoch wasche ich mit Opa das Auto.", "zh": "星期三我和爷爷一起洗车。"}], "pit": "时间放句首时，动词仍在第二位：Am Montag spiele ich Fußball。"}, {"id": "p3", "title": "可分动词 · 频率副词", "rule": "带 auf-、an-、ein-、fern- 等前缀的动词是可分动词：变位的部分放第二位，前缀放句尾。说多常做某事用 immer、oft、manchmal、selten、nie。", "table": [["动词", "句子"], ["aufstehen", "Emma steht um halb sieben auf."], ["fernsehen", "Du siehst nicht fern."], ["einkaufen", "Lisa kauft im Supermarkt ein."], ["aufräumen", "Nach dem Spielen räumst du auf."], ["频率", "immer → oft → manchmal → selten → nie"]], "ex": [{"de": "Emma steht um halb sieben auf.", "zh": "Emma 六点半起床。"}, {"de": "Manchmal isst sie auch einen Apfel.", "zh": "有时她也吃一个苹果。"}], "pit": "be-、ver- 开头的动词不可分：verstehen、besuchen。可分前缀读重音：EINkaufen。"}, {"id": "p4", "title": "zuerst / dann / danach · 换音 a → ä", "rule": "说先后顺序用 zuerst（首先）、dann / danach（然后）。fahren、schlafen、waschen、anfangen 在 du 和 er / sie 时 a 变成 ä。", "table": [["人称", "fahren", "schlafen"], ["ich", "fahre", "schlafe"], ["du", "fährst", "schläfst"], ["er / sie", "fährt", "schläft"], ["wir", "fahren", "schlafen"], ["ihr", "fahrt", "schlaft"]], "ex": [{"de": "Zuerst machen wir die Hausaufgaben, dann räumen wir auf.", "zh": "我们先做作业，然后收拾。"}, {"de": "Wohin fährst du, Lisa?", "zh": "Lisa，你去哪儿？"}], "pit": "zuerst / dann 放句首时，动词紧跟在第二位：Dann sehen wir fern。ihr fahrt 不换音。"}], "test": [{"id": "A1-U7-T01", "t": "pick", "p": "p1", "q": "7:30 → Es ist ___.", "a": "halb acht", "o": ["halb sieben", "acht halb"], "why": "半点说下一个整点的一半：7:30 = halb acht。"}, {"id": "A1-U7-T02", "t": "pick", "p": "p1", "q": "20:00 → Es ist acht Uhr ___.", "a": "abends", "o": ["morgens", "mittags"], "why": "晚上八点：acht Uhr abends。"}, {"id": "A1-U7-T03", "t": "type", "p": "p1", "q": "听时间，写数字（下午，例如 15:00）：___", "a": "14:30", "why": "halb drei = 2:30，下午就是 14:30。", "say": "Es ist halb drei.", "alt": ["2:30", "02:30", "14.30"]}, {"id": "A1-U7-T04", "t": "pick", "p": "p2", "q": "Der Kurs beginnt ___ neun.", "a": "um", "o": ["am", "von"], "why": "具体时刻用 um。", "zh": "课九点开始。"}, {"id": "A1-U7-T05", "t": "pick", "p": "p2", "q": "Ich arbeite ___ acht bis zwölf.", "a": "von", "o": ["um", "am"], "why": "一段时间：von … bis。", "zh": "我从八点工作到十二点。"}, {"id": "A1-U7-T06", "t": "pick", "p": "p2", "q": "___ Freitag sieht Emma fern.", "a": "Am", "o": ["Um", "Im"], "why": "星期几用 am。", "zh": "星期五 Emma 看电视。"}, {"id": "A1-U7-T07", "t": "fix", "p": "p2", "s": "Um Montag spiele ich Fußball.", "bad": "Um", "a": "Am", "o": ["Im", "An"], "why": "星期几用 am（an + dem）。", "zh": "星期一我踢足球。"}, {"id": "A1-U7-T08", "t": "pick", "p": "p3", "q": "Emma steht um halb sieben ___.", "a": "auf", "o": ["an", "ein"], "why": "aufstehen 是可分动词，前缀 auf 放句尾。", "zh": "Emma 六点半起床。"}, {"id": "A1-U7-T09", "t": "order", "p": "p3", "tiles": ["kauft", "im", "Lisa", "ein", "Supermarkt"], "a": "Lisa kauft im Supermarkt ein.", "zh": "Lisa 在超市买东西。", "why": "kauft 在第二位，前缀 ein 放句尾。", "alt": ["Im Supermarkt kauft Lisa ein."]}, {"id": "A1-U7-T10", "t": "pick", "p": "p3", "q": "哪一句正确？___", "a": "Nach dem Spielen räumst du auf.", "o": ["Nach dem Spielen aufräumst du.", "Nach dem Spielen du räumst auf."], "why": "可分动词拆开：räumst 第二位，auf 句尾。"}, {"id": "A1-U7-T11", "t": "pick", "p": "p3", "q": "Emma putzt ___ ihre Zähne.（每次都刷）", "a": "immer", "o": ["nie", "selten"], "why": "每次都 = immer。", "zh": "Emma 每次都刷牙。"}, {"id": "A1-U7-T12", "t": "pick", "p": "p4", "q": "Wohin ___ du, Lisa?", "a": "fährst", "o": ["fahrst", "fährt"], "why": "fahren 换音：du fährst。", "zh": "Lisa，你去哪儿？"}, {"id": "A1-U7-T13", "t": "pick", "p": "p4", "q": "Emma ___ am Wochenende lange.", "a": "schläft", "o": ["schlaft", "schläfst"], "why": "schlafen 换音：er / sie schläft。", "zh": "Emma 周末睡得很晚。"}, {"id": "A1-U7-T14", "t": "order", "p": "p4", "tiles": ["sehen", "Zuerst", "wir", "fern"], "a": "Zuerst sehen wir fern.", "zh": "我们先看电视。", "why": "zuerst 在第一位，动词 sehen 第二，前缀 fern 句尾。", "alt": ["Wir sehen zuerst fern."]}, {"id": "A1-U7-T15", "t": "trans", "p": "p4", "src": "Ich wasche das Auto.", "cue": "换成 er", "q": "Er ___ das Auto.", "a": "wäscht", "o": ["wascht", "wäschst"], "why": "waschen 换音：er wäscht。", "zh": "他在洗车。"}]}, "A1-U8": {"title": "预约", "intro": "Nico 在 Max 和 Tarek 的餐厅等 Lisa，看他们排班、订座、约踢球。这一单元你学会了：Viertel 和正式报时、序数词和日期、können 与 dies- / nächst-，以及 haben 的过去时 hatte。", "points": [{"id": "p1", "title": "Viertel · 正式报时", "rule": "日常说法：Viertel nach / vor（过 / 差一刻），zehn nach / vor（过 / 差十分）。广播、车站等正式场合用 24 小时制，先说小时再说分钟：17:40 = siebzehn Uhr vierzig。", "table": [["时间", "日常说法", "正式说法"], ["12:15", "Viertel nach zwölf", "zwölf Uhr fünfzehn"], ["17:45", "Viertel vor sechs", "siebzehn Uhr fünfundvierzig"], ["17:40", "zwanzig vor sechs", "siebzehn Uhr vierzig"], ["12:30", "halb eins", "zwölf Uhr dreißig"]], "ex": [{"de": "Kommt sie um Viertel nach zwölf oder um halb eins?", "zh": "她十二点一刻来，还是十二点半来？"}, {"de": "Wir haben von neun bis dreiundzwanzig Uhr geöffnet.", "zh": "我们从九点营业到二十三点。"}], "pit": "Viertel vor sechs 是 5:45，不是 6:15。问几点：Wie viel Uhr ist es? / Wie spät ist es?"}, {"id": "p2", "title": "序数词与日期", "rule": "1–19 加 -te，20 以上加 -ste；1、3、7 不规则：erste、dritte、siebte。日期写成 der 17. Januar；“从……到……”用 vom … bis zum …", "table": [["数字", "序数词"], ["1.", "der erste"], ["2.", "der zweite"], ["3.", "der dritte"], ["7.", "der siebte"], ["20.", "der zwanzigste"], ["22.", "der zweiundzwanzigste"]], "ex": [{"de": "Morgen ist der Zweiundzwanzigste.", "zh": "明天是二十二号。"}, {"de": "Vom ersten bis zum siebten November habe ich Frühdienst.", "zh": "十一月一号到七号我上早班。"}], "pit": "问日期：Der Wievielte ist heute? 回答：Heute ist der … 。vom / zum 后面词尾是 -en：vom ersten。"}, {"id": "p3", "title": "können · dies- / nächst-", "rule": "können（能、可以）是情态动词：ich kann、du kannst、er kann（ich 和 er 一样，没有词尾）。diese / nächste + 时间名词，词尾跟着名词的性变。", "table": [["人称", "können"], ["ich", "kann"], ["du", "kannst"], ["er / sie", "kann"], ["wir", "können"], ["ihr", "könnt"], ["sie / Sie", "können"]], "ex": [{"de": "Kannst du am Montag? – Nein, am Montag kann ich nicht.", "zh": "你星期一可以吗？——不行，星期一我不行。"}, {"de": "Diese Woche kann ich nicht, aber nächste Woche geht's.", "zh": "这周我不行，下周可以。"}], "pit": "时间状语用第四格：diesen / nächsten Monat（der），diese / nächste Woche（die），dieses / nächstes Jahr（das）。"}, {"id": "p4", "title": "haben 的过去时：hatte", "rule": "解释过去的情况（比如迟到的原因）常用 hatte。注意区分：“在哪里 / 是什么样”用 war，“有 / 遇到”用 hatte。", "table": [["人称", "现在时", "过去时"], ["ich", "habe", "hatte"], ["du", "hast", "hattest"], ["er / sie", "hat", "hatte"], ["wir", "haben", "hatten"], ["ihr", "habt", "hattet"], ["sie / Sie", "haben", "hatten"]], "ex": [{"de": "Tut mir leid, mein Auto hatte eine Panne.", "zh": "抱歉，我的车出故障了。"}, {"de": "Ich war eine halbe Stunde im Stau.", "zh": "我堵了半个小时。"}], "pit": "ich 和 er / sie 都是 hatte，没有词尾。"}], "test": [{"id": "A1-U8-T01", "t": "pick", "p": "p1", "q": "17:45 → Es ist Viertel ___ sechs.", "a": "vor", "o": ["nach", "halb"], "why": "差一刻六点 = Viertel vor sechs。"}, {"id": "A1-U8-T02", "t": "pick", "p": "p1", "q": "12:15 → Es ist Viertel ___ zwölf.", "a": "nach", "o": ["vor", "halb"], "why": "过一刻 = Viertel nach。"}, {"id": "A1-U8-T03", "t": "pick", "p": "p1", "q": "广播：17:40 → Es ist siebzehn Uhr ___.", "a": "vierzig", "o": ["zwanzig", "vierzehn"], "why": "正式说法：先小时，后分钟。"}, {"id": "A1-U8-T04", "t": "type", "p": "p1", "q": "听时间，写数字（例如 5:40）：___", "a": "5:40", "why": "zwanzig vor sechs = 差二十分六点 = 5:40。", "say": "Es ist zwanzig vor sechs.", "alt": ["17:40", "05:40", "5.40", "17.40"]}, {"id": "A1-U8-T05", "t": "pick", "p": "p2", "q": "Heute ist der ___ Januar.（1.）", "a": "erste", "o": ["einste", "eins"], "why": "1 的序数词不规则：erste。", "zh": "今天是一月一号。"}, {"id": "A1-U8-T06", "t": "pick", "p": "p2", "q": "der 7. → der ___", "a": "siebte", "o": ["siebzehnte", "siebste"], "why": "7 的序数词：siebte。"}, {"id": "A1-U8-T07", "t": "fix", "p": "p2", "s": "Morgen ist der dreite Mai.", "bad": "dreite", "a": "dritte", "o": ["dreie", "drei"], "why": "3 的序数词不规则：dritte。", "zh": "明天是五月三号。"}, {"id": "A1-U8-T08", "t": "type", "p": "p2", "q": "der 20. Januar = der ___ Januar", "a": "zwanzigste", "why": "20 以上加 -ste：zwanzigste。", "hint": "序数词"}, {"id": "A1-U8-T09", "t": "pick", "p": "p3", "q": "___ du am Montag? – Nein, am Montag kann ich nicht.", "a": "Kannst", "o": ["Kann", "Könnt"], "why": "du kannst。", "zh": "你星期一可以吗？——不行。"}, {"id": "A1-U8-T10", "t": "pick", "p": "p3", "q": "Robert ___ am Freitag nicht.", "a": "kann", "o": ["kannt", "könnt"], "why": "er kann，没有词尾。", "zh": "Robert 星期五不行。"}, {"id": "A1-U8-T11", "t": "pick", "p": "p3", "q": "Diese Woche nicht, aber ___ Woche habe ich Zeit.", "a": "nächste", "o": ["nächsten", "nächster"], "why": "die Woche → nächste Woche。", "zh": "这周不行，下周我有空。"}, {"id": "A1-U8-T12", "t": "fix", "p": "p3", "s": "Wir fahren diesen Jahr nach Frankreich.", "bad": "diesen", "a": "dieses", "o": ["diese", "dieser"], "why": "das Jahr → dieses Jahr。", "zh": "我们今年去法国。"}, {"id": "A1-U8-T13", "t": "pick", "p": "p4", "q": "Tut mir leid, mein Auto ___ eine Panne.", "a": "hatte", "o": ["hattest", "hatten"], "why": "er / sie / es hatte。", "zh": "抱歉，我的车出故障了。"}, {"id": "A1-U8-T14", "t": "trans", "p": "p4", "src": "Der Bus hat Verspätung.", "cue": "改成过去时", "q": "Der Bus ___ Verspätung.", "a": "hatte", "o": ["hat", "hattet"], "why": "hat → hatte。", "zh": "公交车晚点了。"}, {"id": "A1-U8-T15", "t": "type", "p": "p4", "q": "Gestern ___ ich keine Zeit.", "a": "hatte", "why": "ich hatte。", "hint": "haben 的过去时", "zh": "昨天我没空。"}]}, "A1-U9": {"title": "各行各业", "intro": "Lisa 去面试，Nico 和 Max、Tarek 聊各种职业，也说出了自己来德国的原因。这一单元你学会了：职业名词的男女形式、情态动词 können / müssen 和框形结构、第三格和表示位置的介词，以及 wollen 和几个情态动词的区别。", "points": [{"id": "p1", "title": "职业名词", "rule": "女性职业一般在男性形式后加 -in，复数是 -innen；有些会变音：Arzt → Ärztin，Koch → Köchin。说自己的职业时不加冠词：Ich bin Lehrerin。", "table": [["男性", "女性", "女性复数"], ["der Lehrer", "die Lehrerin", "die Lehrerinnen"], ["der Arzt", "die Ärztin", "die Ärztinnen"], ["der Koch", "die Köchin", "die Köchinnen"], ["der Anwalt", "die Anwältin", "die Anwältinnen"], ["der Bankkaufmann", "die Bankkauffrau", "—"]], "ex": [{"de": "Ich bin Lehrerin für Deutsch und Englisch.", "zh": "我是德语和英语老师。"}, {"de": "Was ist dein Beruf? / Was bist du von Beruf?", "zh": "你是做什么工作的？"}], "pit": "Ich bin Lehrerin ✓，Ich bin eine Lehrerin ✗（说职业不加冠词）。"}, {"id": "p2", "title": "können / müssen · 框形结构", "rule": "情态动词变位后放第二位，另一个动词用原形放句尾，像一个“框”。können = 能、会；müssen = 必须。", "table": [["主语", "情态动词（第 2 位）", "……", "原形（句尾）"], ["Ich", "muss", "morgen", "arbeiten."], ["Ein Bankkaufmann", "muss", "Kunden", "beraten."], ["Du", "kannst", "gut", "kochen."], ["是非问句", "Kannst", "du gut", "kochen?"]], "ex": [{"de": "Ein Bankkaufmann muss Kunden beraten.", "zh": "银行职员必须为客户提供咨询。"}, {"de": "Du musst E-Mails schreiben.", "zh": "你得写电子邮件。"}], "pit": "müssen：ich muss、du musst、er muss（ich 和 er 一样）。句尾的动词不变位：Du musst schreiben（不是 schreibst）。"}, {"id": "p3", "title": "第三格 · 表示位置的介词", "rule": "回答 Wo?（在哪里）时，in、an、auf、neben、vor、hinter、unter、über 后面用第三格：der / das → dem，die → der，复数 → den（名词加 -n）。in dem = im，an dem = am。", "table": [["", "第一格", "第三格"], ["阳性", "der Flur", "im (in dem) Flur"], ["阴性", "die Cafeteria", "in der Cafeteria"], ["中性", "das Büro", "im (in dem) Büro"], ["复数", "die Räume", "in den Räumen"]], "ex": [{"de": "Die Cafeteria ist in der dritten Etage.", "zh": "咖啡厅在四楼（第三层）。"}, {"de": "Wo ist Herr Müller? – Im Büro.", "zh": "Müller 先生在哪儿？——在办公室。"}], "pit": "第三格里阴性的冠词是 der，看起来像阳性，别搞混。"}, {"id": "p4", "title": "wollen · 情态动词的意思", "rule": "wollen 表示意愿、决心：ich will、du willst、er will。können = 能力 / 可能；müssen = 必须；wollen = 想要（语气比 möchten 强）。", "table": [["情态动词", "意思", "例子"], ["können", "能、会", "Nico kann studieren."], ["müssen", "必须", "Nico muss studieren."], ["wollen", "想要、打算", "Nico will nicht studieren."], ["möchten", "想要（客气）", "Nico möchte Koch werden."]], "ex": [{"de": "Ich will nicht mehr studieren.", "zh": "我不想再读大学了。"}, {"de": "Aber meine Eltern wollen das.", "zh": "但我父母想让我读。"}], "pit": "ich will 不是“我将要”（英语的 will），而是“我想要”。"}], "test": [{"id": "A1-U9-T01", "t": "pick", "p": "p1", "q": "der Lehrer → die ___", "a": "Lehrerin", "o": ["Lehrere", "Lehrerine"], "why": "女性职业加 -in。"}, {"id": "A1-U9-T02", "t": "pick", "p": "p1", "q": "der Arzt → die ___", "a": "Ärztin", "o": ["Arztin", "Ärzte"], "why": "Arzt 变女性时变音：Ärztin。"}, {"id": "A1-U9-T03", "t": "type", "p": "p1", "q": "die Lehrerin → die ___（复数）", "a": "Lehrerinnen", "why": "-in 的复数是 -innen。", "hint": "复数"}, {"id": "A1-U9-T04", "t": "pick", "p": "p1", "q": "Was sind Sie von Beruf? – Ich bin ___.", "a": "Koch", "o": ["ein Koch", "der Koch"], "why": "说职业不加冠词。", "zh": "您是做什么工作的？——我是厨师。"}, {"id": "A1-U9-T05", "t": "pick", "p": "p2", "q": "Ein Bankkaufmann ___ Kunden beraten.", "a": "muss", "o": ["musst", "müssen"], "why": "er muss。", "zh": "银行职员必须为客户提供咨询。"}, {"id": "A1-U9-T06", "t": "order", "p": "p2", "tiles": ["muss", "Ich", "arbeiten", "morgen"], "a": "Ich muss morgen arbeiten.", "zh": "我明天得工作。", "why": "情态动词第二位，原形 arbeiten 放句尾。", "alt": ["Morgen muss ich arbeiten."]}, {"id": "A1-U9-T07", "t": "fix", "p": "p2", "s": "Du musst E-Mails schreibst.", "bad": "schreibst", "a": "schreiben", "o": ["schreibt", "schreibe"], "why": "情态动词后面的动词用原形。", "zh": "你得写电子邮件。"}, {"id": "A1-U9-T08", "t": "trans", "p": "p2", "src": "Ich stehe auf.", "cue": "加上 können", "q": "Ich kann ___.", "a": "aufstehen", "o": ["stehe auf", "aufstehe"], "why": "可分动词的原形合在一起，放句尾：aufstehen。", "zh": "我能起床。"}, {"id": "A1-U9-T09", "t": "pick", "p": "p3", "q": "Wo kann ich Kaffee trinken? – In ___ Cafeteria.", "a": "der", "o": ["die", "dem"], "why": "die Cafeteria，第三格 → der。", "zh": "我在哪儿能喝咖啡？——在咖啡厅。"}, {"id": "A1-U9-T10", "t": "pick", "p": "p3", "q": "Wo ist Herr Müller? – ___ Büro.", "a": "Im", "o": ["In der", "In das"], "why": "das Büro，第三格 → dem；in dem = im。", "zh": "Müller 先生在哪儿？——在办公室。"}, {"id": "A1-U9-T11", "t": "fix", "p": "p3", "s": "Wir warten in die Flur.", "bad": "die", "a": "dem", "o": ["den", "der"], "why": "der Flur，第三格 → dem（in dem Flur = im Flur）。", "zh": "我们在走廊里等。"}, {"id": "A1-U9-T12", "t": "sort", "p": "p3", "q": "第三格用 dem 还是 der？", "cats": ["dem", "der"], "items": [{"w": "Flur", "c": 0}, {"w": "Büro", "c": 0}, {"w": "Raum", "c": 0}, {"w": "Cafeteria", "c": 1}, {"w": "Kantine", "c": 1}, {"w": "Etage", "c": 1}], "why": "阳性、中性 → dem；阴性 → der。"}, {"id": "A1-U9-T13", "t": "pick", "p": "p4", "q": "Ich ___ nicht mehr studieren.", "a": "will", "o": ["wollen", "willst"], "why": "ich will。", "zh": "我不想再读大学了。"}, {"id": "A1-U9-T14", "t": "pick", "p": "p4", "q": "Nico kann studieren, aber er ___ nicht.（他不想）", "a": "will", "o": ["kann", "muss"], "why": "不想 = will nicht。", "zh": "Nico 能读大学，但他不想。"}, {"id": "A1-U9-T15", "t": "pick", "p": "p4", "q": "Mein Vater sagt, ich ___ studieren.（必须）", "a": "muss", "o": ["will", "kann"], "why": "必须 = müssen：ich muss。", "zh": "我爸爸说，我必须读大学。"}]}, "A1-U10": {"title": "东南西北", "intro": "合租公寓的人去度假，Nico 收拾东西；Jürgen 找到了 Yara 的店，Nico 和 Lisa 坐公交过去，店却关着门。这一单元你学会了：bei / von / in der Nähe von、Wo? 用第三格和 Wohin? 用第四格、mit + 交通工具，以及问路指路。", "points": [{"id": "p1", "title": "bei · von · in der Nähe von", "rule": "在某家公司工作用 bei；说某地在哪附近用 in der Nähe von；住在某条街用 in der …straße / …allee / …gasse。这些介词后面都用第三格。", "table": [["说法", "例子"], ["在……工作", "Ich arbeite bei der Post. / beim Bundesamt."], ["在……附近", "in der Nähe vom Bahnhof / von der Oper"], ["住在某条街", "Ich wohne in der Lindenallee 19."], ["缩写", "beim = bei dem，vom = von dem"]], "ex": [{"de": "Das ist im Zentrum, in der Nähe vom Arbeitsamt.", "zh": "那在市中心，劳工局附近。"}, {"de": "Ich kaufe im Supermarkt um die Ecke ein.", "zh": "我在拐角那家超市买东西。"}], "pit": "公司名不带冠词时直接说 bei Siemens；带冠词就要变第三格：bei der Post、beim Rathaus。"}, {"id": "p2", "title": "Wo? 第三格 · Wohin? 第四格", "rule": "in、an、auf、unter、über、vor、hinter、neben、zwischen 是可变格介词：说“在哪里”（Wo?）用第三格，说“到哪里去、放到哪里”（Wohin?）用第四格。", "table": [["", "Wo?（第三格）", "Wohin?（第四格）"], ["der Schrank", "im Schrank", "in den Schrank"], ["die Straße", "in der Straße", "in die Straße"], ["das Regal", "im Regal", "ins Regal"], ["der Tisch", "auf dem Tisch", "auf den Tisch"]], "ex": [{"de": "Das Papier ist im Schrank.", "zh": "纸在柜子里。"}, {"de": "Ich lege das Buch ins Regal.", "zh": "我把书放进书架。"}], "pit": "看动作：东西“待在”某处用第三格（ist、liegt、steht）；把东西“放到”某处或人“走到”某处用第四格（legen、gehen）。ins = in das，im = in dem。"}, {"id": "p3", "title": "mit + 交通工具", "rule": "坐什么交通工具用 mit，mit 永远接第三格：mit dem Bus、mit der U-Bahn、mit dem Fahrrad。走路说 zu Fuß。", "table": [["名词", "mit + 第三格"], ["der Bus / der Zug", "mit dem Bus / mit dem Zug"], ["die U-Bahn / die Straßenbahn", "mit der U-Bahn / mit der Straßenbahn"], ["das Auto / das Fahrrad", "mit dem Auto / mit dem Fahrrad"], ["复数", "mit den Buslinien 9 und 16"], ["走路", "zu Fuß"]], "ex": [{"de": "Wir fahren mit der U-Bahn bis zur Uni. Den Rest gehen wir zu Fuß.", "zh": "我们坐地铁到大学，剩下的路走过去。"}, {"de": "Wie lange dauert die Fahrt?", "zh": "路上要多久？"}], "pit": "mit 后面不会出现 den Bus（第四格）：Ich fahre mit dem Bus。"}, {"id": "p4", "title": "问路和指路", "rule": "正式地给别人指路用祈使句：动词放第一位，后面跟 Sie。常用：geradeaus（直走）、links / rechts（左 / 右）、über die Brücke（过桥）、bis zur Kreuzung（到十字路口）。", "table": [["说法", "意思"], ["Gehen Sie geradeaus.", "直走。"], ["Gehen Sie über die Brücke.", "过桥。"], ["Gehen Sie bis zur Kreuzung.", "走到十字路口。"], ["an der Ampel links", "在红绿灯处往左"], ["auf der rechten Seite", "在右手边"]], "ex": [{"de": "Gehen Sie immer geradeaus.", "zh": "一直往前走。"}, {"de": "Der Laden ist auf der rechten Seite.", "zh": "店在右手边。"}], "pit": "bis zu 后面接第三格：bis zum Park（der / das），bis zur Kreuzung（die）。"}], "test": [{"id": "A1-U10-T01", "t": "pick", "p": "p1", "q": "Ich arbeite ___ der Post.", "a": "bei", "o": ["von", "mit"], "why": "在某个公司或机构工作：bei。", "zh": "我在邮局工作。"}, {"id": "A1-U10-T02", "t": "pick", "p": "p1", "q": "Das Kino ist in der Nähe ___ Bahnhof.", "a": "vom", "o": ["von der", "bei"], "why": "der Bahnhof，第三格 → von dem = vom。", "zh": "电影院在火车站附近。"}, {"id": "A1-U10-T03", "t": "fix", "p": "p1", "s": "Jürgen wohnt in die Lindenallee 19.", "bad": "die", "a": "der", "o": ["den", "dem"], "why": "住在哪里（Wo?）→ 第三格：in der Lindenallee。", "zh": "Jürgen 住在 Lindenallee 19 号。"}, {"id": "A1-U10-T04", "t": "pick", "p": "p1", "q": "Wo arbeiten Sie? – Ich arbeite ___ Siemens.", "a": "bei", "o": ["in", "zu"], "why": "公司名前用 bei。", "zh": "您在哪儿工作？——我在西门子工作。"}, {"id": "A1-U10-T05", "t": "pick", "p": "p2", "q": "Wo ist der Bahnhof? – ___ Zentrum.", "a": "Im", "o": ["Ins", "In den"], "why": "Wo? → 第三格：in dem = im。", "zh": "火车站在哪儿？——在市中心。"}, {"id": "A1-U10-T06", "t": "pick", "p": "p2", "q": "Wohin geht ihr? – Wir gehen ___ Goethestraße.", "a": "in die", "o": ["in der", "im"], "why": "Wohin? → 第四格：in die Goethestraße。", "zh": "你们去哪儿？——我们去歌德街。"}, {"id": "A1-U10-T07", "t": "sort", "p": "p2", "q": "Wo（第三格）还是 Wohin（第四格）？", "cats": ["Wo?（第三格）", "Wohin?（第四格）"], "items": [{"w": "im Regal", "c": 0}, {"w": "auf dem Tisch", "c": 0}, {"w": "neben der Tastatur", "c": 0}, {"w": "ins Regal", "c": 1}, {"w": "auf den Tisch", "c": 1}, {"w": "über den Marktplatz", "c": 1}], "why": "dem / der 是第三格（在哪里）；den / ins 是第四格（到哪里）。"}, {"id": "A1-U10-T08", "t": "fix", "p": "p2", "s": "Ich lege das Buch im Regal.", "bad": "im", "a": "ins", "o": ["in", "am"], "why": "legen 是“放到”，Wohin? → 第四格：ins Regal。", "zh": "我把书放进书架。"}, {"id": "A1-U10-T09", "t": "pick", "p": "p3", "q": "Ich fahre ___ Bus.", "a": "mit dem", "o": ["mit den", "mit der"], "why": "mit + 第三格；der Bus → mit dem Bus。", "zh": "我坐公交车。"}, {"id": "A1-U10-T10", "t": "pick", "p": "p3", "q": "Wir fahren mit ___ U-Bahn bis zur Uni.", "a": "der", "o": ["die", "dem"], "why": "die U-Bahn，第三格 → der。", "zh": "我们坐地铁到大学。"}, {"id": "A1-U10-T11", "t": "type", "p": "p3", "q": "Ich fahre mit ___ Fahrrad zur Arbeit.", "a": "dem", "why": "das Fahrrad，mit + 第三格 → dem。", "hint": "das Fahrrad，第三格", "zh": "我骑自行车去上班。"}, {"id": "A1-U10-T12", "t": "pick", "p": "p3", "q": "Den Rest gehen wir zu ___.", "a": "Fuß", "o": ["Füßen", "Laufen"], "why": "走路：zu Fuß（固定说法）。", "zh": "剩下的路我们走过去。"}, {"id": "A1-U10-T13", "t": "pick", "p": "p4", "q": "___ Sie geradeaus!", "a": "Gehen", "o": ["Geht", "Gehst"], "why": "正式祈使句：动词原形放第一位，后面跟 Sie。", "zh": "请直走！"}, {"id": "A1-U10-T14", "t": "order", "p": "p4", "tiles": ["Sie", "über", "Gehen", "Brücke", "die"], "a": "Gehen Sie über die Brücke.", "zh": "请过桥。", "why": "动词第一，Sie 第二；über die Brücke 是方向，用第四格。"}, {"id": "A1-U10-T15", "t": "pick", "p": "p4", "q": "Der Fahrradladen ist auf der ___ Seite.（右边）", "a": "rechten", "o": ["rechte", "rechts"], "why": "固定说法：auf der rechten / linken Seite。", "zh": "自行车店在右手边。"}]}, "A1-U11": {"title": "饮食与娱乐", "intro": "Nico 搬到 Inge 家暂住，一起做家务、吃饭、聊爱好，还发现自己和 Max、Tarek 都爱钓鱼。这一单元你学会了：nicht 和 kein 的位置、gern / lieber / am liebsten 和 mögen、so … wie 与比较级 + als，以及可分动词和 gehen + 动词原形。", "points": [{"id": "p1", "title": "nicht 和 kein（进阶）", "rule": "kein 否定带 ein 或没有冠词的名词；nicht 否定形容词、副词、带定冠词的名词，或者否定整句——否定整句时 nicht 放在后面（有原形动词时放在原形前）。", "table": [["否定什么", "例子"], ["带 ein 的名词", "Das ist kein Apfel."], ["没有冠词的名词", "Inge isst keine Birnen."], ["形容词 / 副词", "Die Birnen sind nicht frisch. / nicht gern"], ["带定冠词的名词", "Das sind nicht die Birnen von Klara."], ["整句", "Inge isst die Birnen nicht."]], "ex": [{"de": "Ist das ein Apfel? – Nein, das ist kein Apfel. Das ist eine Birne.", "zh": "这是苹果吗？——不，这不是苹果，是梨。"}, {"de": "Sie möchte die Birnen nicht essen.", "zh": "她不想吃这些梨。"}], "pit": "die Birnen（定冠词）用 nicht；Birnen（不带冠词）用 keine。"}, {"id": "p2", "title": "gern / lieber / am liebsten · mögen", "rule": "表示喜好的升级：gern → lieber → am liebsten；gut → besser → am besten；viel → mehr → am meisten。mögen = 喜欢，后面接名词：ich mag、du magst、er mag。", "table": [["原级", "比较级", "最高级"], ["gern", "lieber", "am liebsten"], ["gut", "besser", "am besten"], ["viel", "mehr", "am meisten"], ["mögen", "ich mag / du magst", "er / sie mag"]], "ex": [{"de": "Ich esse gern Tomatensuppe. Aber ich esse lieber Nudeln. Und am liebsten esse ich Pizza.", "zh": "我喜欢喝番茄汤，但更喜欢吃面条，最喜欢吃比萨。"}, {"de": "Möchtest du Apfelsaft oder lieber eine Apfelsaftschorle?", "zh": "你要苹果汁，还是更想要苹果气泡水？"}], "pit": "没有 gerner、gernsten 这种形式。ich mag 和 er mag 一样，没有词尾。问“哪一个”用 welcher / welche / welches。"}, {"id": "p3", "title": "so … wie · 比较级 + als", "rule": "一样：(genau)so + 原级 + wie；不一样：比较级 + als。也可以用 nicht so … wie 表示“不如”。", "table": [["意思", "结构", "例子"], ["一样好", "so gut wie", "Sebastian kocht so gut wie Lisa."], ["一样多", "genauso viel wie", "Max arbeitet genauso viel wie Tarek."], ["更好", "besser als", "Tarek kocht besser als Sebastian."], ["不如", "nicht so viel wie", "Lisa schläft nicht so viel wie Emma."]], "ex": [{"de": "Max putzt mehr als Inge.", "zh": "Max 打扫得比 Inge 多。"}, {"de": "Ich mag Hausarbeit auch nicht.", "zh": "我也不喜欢做家务。"}], "pit": "原级配 wie，比较级配 als，不要混：so gut wie ✓，so gut als ✗；besser als ✓，besser wie ✗。"}, {"id": "p4", "title": "可分动词 · gehen + 动词原形", "rule": "可分动词单独用时前缀放句尾（Ich wasche ab）；和情态动词一起用时合成原形放句尾（Ich möchte abwaschen）。去做某事常用 gehen + 原形：schwimmen gehen、angeln gehen、spazieren gehen。", "table": [["句型", "例子"], ["可分动词单用", "Ich wasche lieber ab."], ["+ 情态动词", "Ich möchte lieber abwaschen."], ["gehen + 原形", "Ich gehe gern angeln."], ["gehen + 原形", "Inge geht im Park spazieren."]], "ex": [{"de": "Möchtest du lieber abwaschen? – Ja, ich wasche lieber ab.", "zh": "你更想洗碗吗？——对，我更愿意洗碗。"}, {"de": "Wir gehen gerne angeln.", "zh": "我们喜欢去钓鱼。"}], "pit": "gehen + 原形里，只有 gehen 变位，另一个动词保持原形放句尾。"}], "test": [{"id": "A1-U11-T01", "t": "pick", "p": "p1", "q": "Ist das ein Apfel? – Nein, das ist ___ Apfel.", "a": "kein", "o": ["nicht", "keinen"], "why": "否定带 ein 的名词：kein Apfel（这里是第一格）。", "zh": "这是苹果吗？——不，这不是苹果。"}, {"id": "A1-U11-T02", "t": "pick", "p": "p1", "q": "Isst Inge Birnen? – Nein, Inge isst ___ Birnen.", "a": "keine", "o": ["nicht", "kein"], "why": "没有冠词的复数名词用 keine。", "zh": "Inge 吃梨吗？——不，Inge 不吃梨。"}, {"id": "A1-U11-T03", "t": "order", "p": "p1", "tiles": ["die", "isst", "nicht", "Birnen", "Inge"], "a": "Inge isst die Birnen nicht.", "zh": "Inge 不吃这些梨。", "why": "否定整句时 nicht 放在句子后面。"}, {"id": "A1-U11-T04", "t": "fix", "p": "p1", "s": "Die Birnen sind kein frisch.", "bad": "kein", "a": "nicht", "o": ["keine", "nichts"], "why": "frisch 是形容词，用 nicht。", "zh": "这些梨不新鲜。"}, {"id": "A1-U11-T05", "t": "pick", "p": "p2", "q": "Ich esse gern Suppe, aber ich esse ___ Nudeln.", "a": "lieber", "o": ["gerner", "mehr gern"], "why": "gern 的比较级是 lieber。", "zh": "我喜欢喝汤，但我更喜欢吃面条。"}, {"id": "A1-U11-T06", "t": "pick", "p": "p2", "q": "Und ___ esse ich Pizza.（最喜欢）", "a": "am liebsten", "o": ["am gernsten", "am meisten"], "why": "gern → lieber → am liebsten；am meisten 是“最多”。", "zh": "我最喜欢吃比萨。"}, {"id": "A1-U11-T07", "t": "pick", "p": "p2", "q": "Bei Max und Tarek schmeckt der Kaffee am ___.", "a": "besten", "o": ["bessten", "gutesten"], "why": "gut → besser → am besten。", "zh": "Max 和 Tarek 那儿的咖啡最好喝。"}, {"id": "A1-U11-T08", "t": "pick", "p": "p2", "q": "Ich ___ keinen Alkohol.", "a": "mag", "o": ["möge", "magst"], "why": "ich mag，没有词尾。", "zh": "我不喜欢喝酒。"}, {"id": "A1-U11-T09", "t": "type", "p": "p2", "q": "___ du Kohlrabi?", "a": "Magst", "why": "du magst；是非问句动词放第一位。", "hint": "mögen", "zh": "你喜欢吃苤蓝吗？"}, {"id": "A1-U11-T10", "t": "pick", "p": "p3", "q": "Tarek kocht besser ___ Sebastian.", "a": "als", "o": ["wie", "so"], "why": "比较级 + als。", "zh": "Tarek 做饭比 Sebastian 好。"}, {"id": "A1-U11-T11", "t": "pick", "p": "p3", "q": "Sebastian kocht so gut ___ Lisa.", "a": "wie", "o": ["als", "so"], "why": "so + 原级 + wie。", "zh": "Sebastian 做饭和 Lisa 一样好。"}, {"id": "A1-U11-T12", "t": "fix", "p": "p3", "s": "Max arbeitet genauso viel als Tarek.", "bad": "als", "a": "wie", "o": ["so", "mehr"], "why": "genauso + 原级要配 wie。", "zh": "Max 和 Tarek 工作得一样多。"}, {"id": "A1-U11-T13", "t": "trans", "p": "p4", "src": "Ich wasche ab.", "cue": "加上 möchte", "q": "Ich möchte ___.", "a": "abwaschen", "o": ["wasche ab", "abwasche"], "why": "和情态动词一起用时，可分动词合成原形放句尾。", "zh": "我想洗碗。"}, {"id": "A1-U11-T14", "t": "pick", "p": "p4", "q": "Inge geht im Park ___.", "a": "spazieren", "o": ["spaziert", "spazierst"], "why": "gehen + 动词原形：spazieren gehen。", "zh": "Inge 在公园散步。"}, {"id": "A1-U11-T15", "t": "order", "p": "p4", "tiles": ["gern", "gehe", "angeln", "Ich"], "a": "Ich gehe gern angeln.", "zh": "我喜欢去钓鱼。", "why": "gehen 变位放第二位，angeln 用原形放句尾。", "alt": ["Gern gehe ich angeln."]}]}, "A1-U12": {"title": "食品", "intro": "Nico 和 Inge 一起采购：面包店、集市、超市，再回家照着菜谱做比萨。这一单元你学会了：数量单位、购物用语、in / auf + 商店，以及菜谱和说明里的指令。", "points": [{"id": "p1", "title": "数量单位", "rule": "买东西时：数量 + 单位 + 东西，中间不加任何词：ein Kilo Äpfel、ein Pfund Tomaten（ein Pfund = 500 克）。Gramm、Kilo、Pfund、Liter、Stück 前面数字再大也不变复数；Flasche、Dose、Packung 要变复数。可数的东西用复数：ein Kilo Äpfel。", "table": [["单位", "例子"], ["Gramm / Kilo / Pfund", "300 Gramm Datteln / ein Kilo Bananen / ein Pfund Tomaten"], ["Liter", "ein Liter Milch"], ["Stück", "zwei Stück Apfelkuchen"], ["Flasche / Dose", "eine Flasche Öl / zwei Dosen Mais"], ["Tafel / Packung", "eine Tafel Schokolade / eine Packung Reis"]], "ex": [{"de": "Ich hätte gern ein Pfund Tomaten und drei Gurken.", "zh": "我要一磅番茄和三根黄瓜。"}, {"de": "Ein Kilo Bananen kostet 1,10 Euro.", "zh": "一公斤香蕉 1.10 欧元。"}], "pit": "zwei Stück Kuchen ✓，zwei Stücke Kuchen ✗；zwei Flaschen Wasser ✓。"}, {"id": "p2", "title": "购物用语 · 问价格", "rule": "客气地要东西：Ich hätte gern …；店员问：Was darf es sein? / Darf es sonst noch etwas sein?。问价格三种说法：Was kostet …? / Wie viel kostet …? / Wie teuer ist …? 动词要跟主语单复数一致。", "table": [["说法", "意思"], ["Ich hätte gern …", "我想要……"], ["Was darf es sein?", "您要点什么？"], ["Darf es sonst noch etwas sein?", "还要别的吗？"], ["Das ist alles.", "就这些。"], ["Was kostet / kosten …?", "……多少钱？"], ["Wie teuer ist / sind …?", "……多贵？"]], "ex": [{"de": "Was kostet das Roggenbrot? – 3,20 Euro.", "zh": "黑麦面包多少钱？——3.20 欧元。"}, {"de": "Wie viel kosten die Gurken?", "zh": "黄瓜多少钱？"}], "pit": "die Gurken 是复数 → kosten / sind；ein Kilo Bananen 的主语是 ein Kilo → kostet。"}, {"id": "p3", "title": "在哪儿买：in / auf + 第三格", "rule": "在商店里买用 in + 第三格：im Supermarkt、in der Bäckerei、in der Metzgerei；在集市上用 auf + 第三格：auf dem Markt。", "table": [["地方", "说法"], ["der Supermarkt", "im Supermarkt"], ["die Bäckerei", "in der Bäckerei"], ["die Metzgerei", "in der Metzgerei"], ["der Markt", "auf dem Markt"], ["der Wochenmarkt", "auf dem Wochenmarkt"]], "ex": [{"de": "Inge kauft auf dem Markt ein.", "zh": "Inge 在集市上买东西。"}, {"de": "Brötchen kaufen wir in der Bäckerei.", "zh": "小面包我们在面包店买。"}], "pit": "集市是露天的“平面”，用 auf；商店是“里面”，用 in。"}, {"id": "p4", "title": "指令：正式祈使句 · 不定式", "rule": "菜谱、说明书里给指令有两种写法：正式祈使句（动词第一 + Sie）或者不定式写法（没有主语，原形放句尾）。", "table": [["写法", "例子"], ["正式祈使句", "Schneiden Sie den Käse in Würfel."], ["正式祈使句", "Legen Sie alles auf die Pizza."], ["不定式", "Den Käse in Würfel schneiden."], ["不定式", "Die Pizza in den Ofen schieben."]], "ex": [{"de": "Schieben Sie die Pizza für 20 Minuten bei 180 Grad in den Ofen.", "zh": "把比萨放进烤箱，180 度烤 20 分钟。"}, {"de": "Du schneidest den Fetakäse in kleine Stücke.", "zh": "你把羊奶酪切成小块。"}], "pit": "正式祈使句的动词就是 Sie 的形式：Schneiden Sie …（不是 Schneidet Sie）。"}], "test": [{"id": "A1-U12-T01", "t": "pick", "p": "p1", "q": "Ich hätte gern ein ___ Tomaten.（500 克）", "a": "Pfund", "o": ["Kilo", "Liter"], "why": "ein Pfund = 500 克。", "zh": "我要一磅番茄。"}, {"id": "A1-U12-T02", "t": "pick", "p": "p1", "q": "eine ___ Olivenöl", "a": "Flasche", "o": ["Tafel", "Stück"], "why": "液体装瓶：eine Flasche Öl。", "zh": "一瓶橄榄油"}, {"id": "A1-U12-T03", "t": "pick", "p": "p1", "q": "eine ___ Schokolade", "a": "Tafel", "o": ["Flasche", "Liter"], "why": "一板巧克力：eine Tafel Schokolade。", "zh": "一板巧克力"}, {"id": "A1-U12-T04", "t": "fix", "p": "p1", "s": "Ich nehme zwei Stücke Apfelkuchen.", "bad": "Stücke", "a": "Stück", "o": ["Stücken", "Stückes"], "why": "作数量单位时 Stück 不变复数。", "zh": "我要两块苹果蛋糕。"}, {"id": "A1-U12-T05", "t": "pick", "p": "p2", "q": "___ gerne ein Brot.", "a": "Ich hätte", "o": ["Ich bin", "Ich hatte"], "why": "客气地要东西：Ich hätte gern(e) …", "zh": "我想要一个面包。"}, {"id": "A1-U12-T06", "t": "pick", "p": "p2", "q": "Wie viel ___ die Gurken?", "a": "kosten", "o": ["kostet", "kostest"], "why": "die Gurken 是复数 → kosten。", "zh": "黄瓜多少钱？"}, {"id": "A1-U12-T07", "t": "pick", "p": "p2", "q": "Wie teuer ___ das Fleisch?", "a": "ist", "o": ["sind", "kostet"], "why": "das Fleisch 是单数：Wie teuer ist …?", "zh": "肉多少钱？"}, {"id": "A1-U12-T08", "t": "trans", "p": "p2", "src": "Was kostet die Tomate?", "cue": "换成复数 die Tomaten", "q": "Was ___ die Tomaten?", "a": "kosten", "o": ["kostet", "kosteten"], "why": "复数主语 → kosten。", "zh": "番茄多少钱？"}, {"id": "A1-U12-T09", "t": "pick", "p": "p3", "q": "Inge kauft ___ Markt ein.", "a": "auf dem", "o": ["im", "in der"], "why": "集市用 auf：auf dem Markt。", "zh": "Inge 在集市上买东西。"}, {"id": "A1-U12-T10", "t": "pick", "p": "p3", "q": "Brot kaufen wir ___ Bäckerei.", "a": "in der", "o": ["im", "auf der"], "why": "die Bäckerei，商店里 → in der。", "zh": "面包我们在面包店买。"}, {"id": "A1-U12-T11", "t": "sort", "p": "p3", "q": "用 in 还是 auf？", "cats": ["in（im / in der）", "auf（auf dem）"], "items": [{"w": "Supermarkt", "c": 0}, {"w": "Bäckerei", "c": 0}, {"w": "Metzgerei", "c": 0}, {"w": "Markt", "c": 1}, {"w": "Wochenmarkt", "c": 1}], "why": "商店用 in，集市用 auf。"}, {"id": "A1-U12-T12", "t": "pick", "p": "p4", "q": "___ Sie zuerst den Käse klein.", "a": "Schneiden", "o": ["Schneidet", "Schneidest"], "why": "正式祈使句：动词原形 + Sie。", "zh": "请先把奶酪切小。"}, {"id": "A1-U12-T13", "t": "order", "p": "p4", "tiles": ["Sie", "die", "Ofen", "Schieben", "in", "Pizza", "den"], "a": "Schieben Sie die Pizza in den Ofen.", "zh": "请把比萨放进烤箱。", "why": "动词第一，Sie 第二；in den Ofen 是方向，第四格。"}, {"id": "A1-U12-T14", "t": "trans", "p": "p4", "src": "Schneiden Sie den Käse in Würfel.", "cue": "改成菜谱里的不定式写法", "q": "Den Käse in Würfel ___.", "a": "schneiden", "o": ["schneiden Sie", "schneidet"], "why": "不定式写法：没有主语，原形放句尾。", "zh": "把奶酪切成丁。"}, {"id": "A1-U12-T15", "t": "type", "p": "p4", "q": "___ Sie alles auf die Pizza.", "a": "Legen", "why": "正式祈使句：Legen Sie …", "hint": "legen，正式祈使句", "zh": "请把所有东西放到比萨上。"}]}}, "eps": {"A1-1": {"p": ["p1", "p2"], "items": [{"id": "A1-1-01", "t": "pick", "p": "p1", "q": "Frau Schneider, wie geht es ___?", "a": "Ihnen", "o": ["dir", "du"], "zh": "Schneider 女士，您好吗？", "why": "对 Frau + 姓 用 Sie：Wie geht es Ihnen?"}, {"id": "A1-1-02", "t": "pick", "p": "p1", "q": "Hallo, Sarah! Wie geht's ___?", "a": "dir", "o": ["Ihnen", "Sie"], "zh": "你好，Sarah！你好吗？", "why": "叫名字的熟人用 du：Wie geht's dir?"}, {"id": "A1-1-03", "t": "pick", "p": "p2", "q": "白天见到 Frau Kamp：___, Frau Kamp!", "a": "Guten Tag", "o": ["Tschüss", "Gute Nacht"], "zh": "您好，Kamp 女士！", "why": "见面打招呼用 Guten Tag；Tschüss 和 Gute Nacht 是道别。"}, {"id": "A1-1-04", "t": "fix", "p": "p1", "s": "Danke, gut! Und dir, Herr Müller?", "bad": "dir", "a": "Ihnen", "o": ["du", "dich"], "zh": "谢谢，很好！那您呢，Müller 先生？", "why": "对 Herr Müller 用 Sie：Und Ihnen?"}, {"id": "A1-1-05", "t": "order", "p": "p1", "tiles": ["es", "Ihnen", "Wie", "geht"], "a": "Wie geht es Ihnen?", "zh": "您好吗？", "why": "W 问句：Wie 第一，动词 geht 第二。"}, {"id": "A1-1-06", "t": "pick", "p": "p2", "q": "Hey, Lena! Na, wie ___?", "a": "geht's", "o": ["gehst", "heißt"], "zh": "嘿，Lena！怎么样？", "why": "熟人问候：Na, wie geht's?（geht's = geht es）"}]}, "A1-2": {"p": ["p3"], "items": [{"id": "A1-2-01", "t": "sort", "p": "p3", "q": "按冠词分类", "cats": ["der", "die", "das"], "items": [{"w": "Flughafen", "c": 0}, {"w": "Tasche", "c": 1}, {"w": "Taxi", "c": 2}, {"w": "Bus", "c": 0}, {"w": "Musik", "c": 1}, {"w": "Hotel", "c": 2}], "why": "der Flughafen, der Bus · die Tasche, die Musik · das Taxi, das Hotel"}, {"id": "A1-2-02", "t": "pick", "p": "p3", "q": "___ Flughafen ist groß.", "a": "Der", "o": ["Die", "Das"], "zh": "机场很大。", "why": "der Flughafen"}, {"id": "A1-2-03", "t": "pick", "p": "p3", "q": "Wo ist ___ Toilette?", "a": "die", "o": ["der", "das"], "zh": "厕所在哪里？", "why": "die Toilette：-e 结尾，阴性。"}, {"id": "A1-2-04", "t": "type", "p": "p3", "q": "___ Problem", "hint": "冠词", "a": "das", "zh": "问题；麻烦", "why": "das Problem"}, {"id": "A1-2-05", "t": "fix", "p": "p3", "s": "Das taxi fährt ins Zentrum.", "bad": "taxi", "a": "Taxi", "o": ["TAXI", "taxis"], "zh": "出租车开往市中心。", "why": "名词首字母一律大写。"}, {"id": "A1-2-06", "t": "pick", "p": "p3", "q": "Musik 以 -ik 结尾，冠词是 ___", "a": "die", "o": ["der", "das"], "why": "-ik 结尾的名词是阴性：die Musik。"}]}, "A1-3": {"p": ["p1", "p2"], "items": [{"id": "A1-3-01", "t": "pick", "p": "p1", "q": "Lisa 问 Nico：Brauchst ___ Hilfe?", "a": "du", "o": ["Sie", "Ihnen"], "zh": "你需要帮忙吗？", "why": "brauchst 是 du 的形式，主语是 du。"}, {"id": "A1-3-02", "t": "trans", "p": "p1", "src": "Brauchst du Hilfe?", "cue": "对出租车司机说（正式）", "q": "Brauchen ___ Hilfe?", "a": "Sie", "o": ["du", "dir"], "zh": "您需要帮忙吗？", "why": "正式场合用 Sie，动词随之变成 brauchen。"}, {"id": "A1-3-03", "t": "fix", "p": "p1", "s": "Herr Tillmanns, wie geht es dir?", "bad": "dir", "a": "Ihnen", "o": ["du", "dich"], "zh": "Tillmanns 先生，您好吗？", "why": "对 Herr + 姓 用 Sie：wie geht es Ihnen?"}, {"id": "A1-3-04", "t": "pick", "p": "p2", "q": "朋友要坐飞机走了：___!", "a": "Gute Reise", "o": ["Guten Morgen", "Gute Nacht"], "zh": "一路顺风！", "why": "送人出行说 Gute Reise!"}, {"id": "A1-3-05", "t": "pick", "p": "p2", "q": "正式告别：___, Herr Tillmanns!", "a": "Auf Wiedersehen", "o": ["Hallo", "Guten Tag"], "zh": "再见，Tillmanns 先生！", "why": "Hallo、Guten Tag 是见面时说的；正式告别说 Auf Wiedersehen。"}, {"id": "A1-3-06", "t": "order", "p": "p1", "tiles": ["Hilfe", "du", "Brauchst"], "a": "Brauchst du Hilfe?", "zh": "你需要帮忙吗？", "why": "是非问句：动词放第一位。"}]}, "A1-4": {"p": ["p4"], "items": [{"id": "A1-4-01", "t": "type", "p": "p4", "say": "En. I. Tse. O.", "q": "听拼写，写出名字：___", "a": "Nico", "why": "N – I – C – O，C 读作 tse。"}, {"id": "A1-4-02", "t": "type", "p": "p4", "say": "Üpsilon. A. Er. A.", "q": "听拼写，写出名字：___", "a": "Yara", "why": "Y 读 üpsilon，R 读 er。"}, {"id": "A1-4-03", "t": "pick", "p": "p4", "q": "W 的德语读法是：___", "a": "we", "o": ["doppel-u", "wo"], "why": "德语 W 读 we，V 读 fau。"}, {"id": "A1-4-04", "t": "pick", "p": "p4", "q": "„Jot“ 是哪个字母？___", "a": "J", "o": ["Y", "G"], "why": "J 读 jot。"}, {"id": "A1-4-05", "t": "pick", "p": "p4", "q": "Wie ___ man das?", "a": "schreibt", "o": ["heißt", "kommt"], "zh": "这个怎么写？", "why": "Wie schreibt man das? 问拼写。"}, {"id": "A1-4-06", "t": "order", "p": "p4", "tiles": ["buchstabiere", "Bitte", "das"], "a": "Bitte buchstabiere das!", "alt": ["Buchstabiere das bitte!"], "zh": "请拼一下！", "why": "请求句：动词 buchstabiere 可以放句首，bitte 放前放后都行。"}]}, "A1-5": {"p": ["p1"], "items": [{"id": "A1-5-01", "t": "pick", "p": "p1", "q": "Hallo, ich ___ Lisa.", "a": "heiße", "o": ["heißt", "heißen"], "zh": "你好，我叫 Lisa。", "why": "ich heiße"}, {"id": "A1-5-02", "t": "pick", "p": "p1", "q": "Und wie ___ du?", "a": "heißt", "o": ["heiße", "heißen"], "zh": "那你叫什么名字？", "why": "du heißt"}, {"id": "A1-5-03", "t": "pick", "p": "p1", "q": "Das ___ Emma.", "a": "ist", "o": ["bin", "bist"], "zh": "这是 Emma。", "why": "Das ist …：介绍别人用 ist。"}, {"id": "A1-5-04", "t": "fix", "p": "p1", "s": "Du heißst Nico.", "bad": "heißst", "a": "heißt", "o": ["heiße", "heißen"], "zh": "你叫 Nico。", "why": "heißen 的词干以 ß 结尾，du 只加 -t：du heißt。"}, {"id": "A1-5-05", "t": "type", "p": "p1", "q": "Ich ___ Nico.", "hint": "sein", "a": "bin", "zh": "我是 Nico。", "why": "ich bin"}, {"id": "A1-5-06", "t": "trans", "p": "p1", "src": "Wie heißt du?", "cue": "改成正式的 Sie", "q": "Wie ___ Sie?", "a": "heißen", "o": ["heißt", "heiße"], "zh": "您叫什么名字？", "why": "Sie 用 heißen。"}]}, "A1-6": {"p": ["p2"], "items": [{"id": "A1-6-01", "t": "pick", "p": "p2", "q": "Das ist Lisa. ___ ist nett.", "a": "Sie", "o": ["Er", "Es"], "zh": "这是 Lisa。她人很好。", "why": "说女人用 sie。"}, {"id": "A1-6-02", "t": "pick", "p": "p2", "q": "Nico lernt Deutsch. ___ kommt aus Spanien.", "a": "Er", "o": ["Sie", "Es"], "zh": "Nico 在学德语。他来自西班牙。", "why": "说男人用 er。"}, {"id": "A1-6-03", "t": "pick", "p": "p2", "q": "Er ist Taxifahrer. Sie ist ___.", "a": "Taxifahrerin", "o": ["Taxifahrer", "Taxifahrerine"], "zh": "他是出租车司机。她是女出租车司机。", "why": "女性职业加 -in：die Taxifahrerin。"}, {"id": "A1-6-04", "t": "pick", "p": "p2", "q": "der Vorname = vor + der Name → 冠词是 ___", "a": "der", "o": ["die", "das"], "zh": "名字（不含姓）", "why": "复合词看最后一个词：der Name。"}, {"id": "A1-6-05", "t": "fix", "p": "p2", "s": "Lisa Brunner? Er ist sehr nett.", "bad": "Er", "a": "Sie", "o": ["Es", "Ich"], "zh": "Lisa Brunner？她人很好。", "why": "Lisa 是女性，用 sie。"}, {"id": "A1-6-06", "t": "type", "p": "p2", "q": "der Deutschlehrer → die ___", "hint": "女性", "a": "Deutschlehrerin", "zh": "女德语老师", "why": "加 -in：die Deutschlehrerin。"}]}, "A1-7": {"p": ["p3"], "items": [{"id": "A1-7-01", "t": "pick", "p": "p3", "q": "Max ___ aus Deutschland.", "a": "kommt", "o": ["kommst", "komme"], "zh": "Max 来自德国。", "why": "er 的词尾是 -t。"}, {"id": "A1-7-02", "t": "pick", "p": "p3", "q": "Ich ___ in Sevilla.", "a": "wohne", "o": ["wohnst", "wohnt"], "zh": "我住在塞维利亚。", "why": "ich 的词尾是 -e。"}, {"id": "A1-7-03", "t": "type", "p": "p3", "q": "Was ___ du jetzt?", "hint": "machen", "a": "machst", "zh": "你现在做什么？", "why": "mach + st → machst。"}, {"id": "A1-7-04", "t": "order", "p": "p3", "tiles": ["du", "kommst", "Woher"], "a": "Woher kommst du?", "zh": "你从哪里来？", "why": "疑问词第一，动词第二。"}, {"id": "A1-7-05", "t": "fix", "p": "p3", "s": "Woher kommt du?", "bad": "kommt", "a": "kommst", "o": ["komme", "kommen"], "zh": "你从哪里来？", "why": "du 的词尾是 -st。"}, {"id": "A1-7-06", "t": "pick", "p": "p3", "q": "___ wohnst du? – In Sevilla.", "a": "Wo", "o": ["Woher", "Was"], "zh": "你住在哪里？——在塞维利亚。", "why": "问“在哪里”用 Wo；Woher 问“从哪里来”。"}]}, "A1-8": {"p": ["p4"], "items": [{"id": "A1-8-01", "t": "pick", "p": "p4", "q": "Nico ___ ein Foto von Yara.", "a": "hat", "o": ["habe", "hast"], "zh": "Nico 有一张 Yara 的照片。", "why": "er/sie hat"}, {"id": "A1-8-02", "t": "pick", "p": "p4", "q": "Ich ___ ein Problem.", "a": "habe", "o": ["hat", "hast"], "zh": "我有个麻烦。", "why": "ich habe"}, {"id": "A1-8-03", "t": "pick", "p": "p4", "q": "Das ist ___ Foto.", "a": "ein", "o": ["eine", "einen"], "zh": "这是一张照片。", "why": "das Foto → ein Foto。"}, {"id": "A1-8-04", "t": "pick", "p": "p4", "q": "Yara hat ___ Fahrradgeschäft.", "a": "ein", "o": ["eine", "einen"], "zh": "Yara 有一家自行车店。", "why": "das Geschäft（复合词看最后一个词）→ ein Fahrradgeschäft。"}, {"id": "A1-8-05", "t": "trans", "p": "p4", "src": "Ich habe ein Foto.", "cue": "改成否定", "q": "Ich habe ___ Foto.", "a": "kein", "o": ["keine", "nicht"], "zh": "我没有照片。", "why": "ein Foto → kein Foto；否定带 ein 的名词用 kein-。"}, {"id": "A1-8-06", "t": "fix", "p": "p4", "s": "Da ist kein Tasche.", "bad": "kein", "a": "keine", "o": ["keinen", "nicht"], "zh": "那里没有包。", "why": "die Tasche 是阴性，用 keine。"}]}, "A1-9": {"p": ["p1", "p3"], "items": [{"id": "A1-9-01", "t": "type", "p": "p1", "say": "zwölf", "q": "听数字，用阿拉伯数字写出来：___", "a": "12", "why": "zwölf = 12，0–12 要单独记。"}, {"id": "A1-9-02", "t": "pick", "p": "p1", "q": "83 = ___", "a": "dreiundachtzig", "o": ["achtunddreißig", "dreiachtzig"], "why": "个位在前：3（drei）+ und + 80（achtzig）。"}, {"id": "A1-9-03", "t": "pick", "p": "p1", "q": "30 = ___", "a": "dreißig", "o": ["dreizig", "dreizehn"], "why": "30 是唯一用 ß 的整十：dreißig；dreizehn 是 13。"}, {"id": "A1-9-04", "t": "fix", "p": "p1", "s": "Lotte wird achtzig Jahre alt.", "bad": "achtzig", "a": "acht", "o": ["achtzehn", "achte"], "zh": "Lotte 满八岁。", "why": "8 = acht，18 = achtzehn，80 = achtzig。Lotte 过的是八岁生日。"}, {"id": "A1-9-05", "t": "sort", "p": "p1", "q": "这些数是“十几”还是“几十”？", "cats": ["十几（13–19）", "几十（20–90）"], "items": [{"w": "dreizehn", "c": 0}, {"w": "siebzehn", "c": 0}, {"w": "neunzehn", "c": 0}, {"w": "zwanzig", "c": 1}, {"w": "siebzig", "c": 1}, {"w": "neunzig", "c": 1}], "why": "-zehn 结尾是十几，-zig 结尾是几十（30 是 dreißig）。"}, {"id": "A1-9-06", "t": "pick", "p": "p3", "q": "Wie ___ Zahlen sind das? – Das sind zwölf Zahlen.", "a": "viele", "o": ["alt", "oft"], "zh": "这是多少个数字？——一共十二个。", "why": "问可数的东西有多少：Wie viele + 复数名词。"}]}, "A1-10": {"p": ["p2"], "items": [{"id": "A1-10-01", "t": "pick", "p": "p2", "q": "Wie alt ___ Sie?", "a": "sind", "o": ["haben", "ist"], "zh": "您多大年纪？", "why": "问年龄用 sein，Sie 的形式是 sind。"}, {"id": "A1-10-02", "t": "fix", "p": "p2", "s": "Emma hat acht Jahre alt.", "bad": "hat", "a": "ist", "o": ["habe", "bin"], "zh": "Emma 八岁。", "why": "说年龄用 sein：Emma ist acht Jahre alt。"}, {"id": "A1-10-03", "t": "type", "p": "p2", "say": "null, eins, sieben, drei", "q": "听号码，写出数字：___", "a": "0173", "alt": ["0 1 7 3"], "why": "手机号码一位一位地读：null, eins, sieben, drei。"}, {"id": "A1-10-04", "t": "pick", "p": "p2", "q": "Meine Telefonnummer ___ 0800 777 33 44.", "a": "ist", "o": ["hat", "sind"], "zh": "我的电话号码是 0800 777 33 44。", "why": "Meine Telefonnummer ist …：号码是单数，用 ist。"}, {"id": "A1-10-05", "t": "trans", "p": "p2", "src": "Wie ist deine Handynummer?", "cue": "改成正式的 Sie", "q": "Wie ist ___ Handynummer?", "a": "Ihre", "o": ["deine", "Ihr"], "zh": "您的手机号是多少？", "why": "正式用 Ihre（die Handynummer 是阴性）。"}, {"id": "A1-10-06", "t": "pick", "p": "p2", "q": "777 可以读成：dreimal die ___", "a": "Sieben", "o": ["Siebzig", "Siebzehn"], "zh": "三个 7", "why": "读号码时可以说“几次某个数字”：dreimal die Sieben = 三个 7。"}]}, "A1-11": {"p": ["p3"], "items": [{"id": "A1-11-01", "t": "pick", "p": "p3", "q": "___ ist da? – Hier ist Nico.", "a": "Wer", "o": ["Was", "Wo"], "zh": "是谁？——我是 Nico。", "why": "问人用 Wer。"}, {"id": "A1-11-02", "t": "pick", "p": "p3", "q": "___ geht's dir? – Nicht so gut.", "a": "Wie", "o": ["Wo", "Was"], "zh": "你怎么样？——不太好。", "why": "问状况用 Wie：Wie geht's dir?"}, {"id": "A1-11-03", "t": "pick", "p": "p3", "q": "Nicht so gut? ___ nicht?", "a": "Warum", "o": ["Wer", "Woher"], "zh": "不太好？为什么？", "why": "问原因用 Warum。"}, {"id": "A1-11-04", "t": "order", "p": "p3", "tiles": ["bist", "du", "Wo"], "a": "Wo bist du?", "zh": "你在哪儿？", "why": "疑问词 Wo 第一，动词 bist 第二。"}, {"id": "A1-11-05", "t": "fix", "p": "p3", "s": "Ich komme in Spanien.", "bad": "in", "a": "aus", "o": ["von", "nach"], "zh": "我来自西班牙。", "why": "来自哪里：kommen aus …；in 用来说住在哪里。"}, {"id": "A1-11-06", "t": "pick", "p": "p3", "q": "Die Polizei ist ___ der Schreinerstraße.", "a": "in", "o": ["aus", "nach"], "zh": "警察局在 Schreinerstraße。", "why": "在某条街上：in der …straße。"}]}, "A1-12": {"p": ["p4"], "items": [{"id": "A1-12-01", "t": "type", "p": "p4", "say": "zweihundertzwölf", "q": "听数字，用阿拉伯数字写出来：___", "a": "212", "why": "zweihundert（200）+ zwölf（12）= 212。"}, {"id": "A1-12-02", "t": "pick", "p": "p4", "q": "545 = ___", "a": "fünfhundertfünfundvierzig", "o": ["fünfhundertvierundfünfzig", "fünfundvierzighundertfünf"], "why": "先说 fünfhundert，再说 45（5 + und + 40）。"}, {"id": "A1-12-03", "t": "pick", "p": "p4", "q": "1000 = ___", "a": "tausend", "o": ["zehnhundert", "hunderttausend"], "why": "1000 = (ein)tausend；hunderttausend 是 100 000。"}, {"id": "A1-12-04", "t": "trans", "p": "p4", "src": "Wie ist deine Adresse?", "cue": "在警察局（正式）", "q": "Wie ist ___ Adresse?", "a": "Ihre", "o": ["deine", "Ihr"], "zh": "您的地址是什么？", "why": "在机关里用 Sie：die Adresse → Ihre Adresse。"}, {"id": "A1-12-05", "t": "sort", "p": "p4", "q": "哪句是正式问法，哪句是对熟人说的？", "cats": ["正式（Sie）", "熟人（du）"], "items": [{"w": "Wie ist Ihre Adresse?", "c": 0}, {"w": "Welche Nummer haben Sie?", "c": 0}, {"w": "Wie alt bist du?", "c": 1}, {"w": "Wo wohnst du?", "c": 1}], "why": "Sie / Ihre 是正式；du / deine 是熟人。在警察局，Jürgen 对 Nico 用的是 Sie。"}, {"id": "A1-12-06", "t": "fix", "p": "p4", "s": "Meine Hausnummer ist hundertsechsunddreizig.", "bad": "hundertsechsunddreizig", "a": "hundertsechsunddreißig", "o": ["hundertdreiundsechzig", "hundertsechsunddreizehn"], "zh": "我的门牌号是 136。", "why": "30 是 dreißig（ß），所以 136 = hundertsechsunddreißig。"}]}, "A1-13": {"p": ["p1", "p2"], "items": [{"id": "A1-13-01", "t": "pick", "p": "p1", "q": "Hi, Lisa! ___ ist denn das?", "a": "Wer", "o": ["Was", "Wie"], "why": "问人用 wer。", "zh": "嗨，Lisa！这是谁呀？"}, {"id": "A1-13-02", "t": "pick", "p": "p2", "q": "Nico, ___ du etwas trinken?", "a": "möchtest", "o": ["möchte", "möchtet"], "why": "du möchtest。", "zh": "Nico，你想喝点什么吗？"}, {"id": "A1-13-03", "t": "pick", "p": "p2", "q": "Heute Abend ___ es eine Party.", "a": "gibt", "o": ["hat", "ist"], "why": "表示“有……（存在）”用 es gibt。", "zh": "今晚有个派对。"}, {"id": "A1-13-04", "t": "fix", "p": "p1", "s": "Was ist Yara? – Yara ist Nicos Tante.", "bad": "Was", "a": "Wer", "o": ["Wo", "Wie"], "why": "问人用 wer：Wer ist Yara?", "zh": "Yara 是谁？——Yara 是 Nico 的阿姨。"}, {"id": "A1-13-05", "t": "trans", "p": "p2", "src": "Möchtest du etwas trinken?", "cue": "问 Lisa 和 Nina 两个人（ihr）", "q": "___ ihr etwas trinken?", "a": "Möchtet", "o": ["Möchten", "Möchtest"], "why": "ihr 的形式是 möchtet。", "zh": "你们想喝点什么吗？"}, {"id": "A1-13-06", "t": "order", "p": "p2", "tiles": ["etwas", "Möchtest", "trinken", "du"], "a": "Möchtest du etwas trinken?", "zh": "你想喝点什么吗？", "why": "是非问句：变位动词 möchtest 第一，动词原形 trinken 放句尾。"}]}, "A1-14": {"p": ["p1", "p2"], "items": [{"id": "A1-14-01", "t": "sort", "p": "p1", "q": "按冠词分类", "cats": ["der", "die", "das"], "items": [{"w": "Saft", "c": 0}, {"w": "Wein", "c": 0}, {"w": "Cola", "c": 1}, {"w": "Limo", "c": 1}, {"w": "Wasser", "c": 2}, {"w": "Eis", "c": 2}], "why": "der Saft、der Wein · die Cola、die Limo · das Wasser、das Eis"}, {"id": "A1-14-02", "t": "pick", "p": "p1", "q": "___ Milch ist im Kühlschrank.", "a": "Die", "o": ["Der", "Das"], "why": "die Milch 是阴性。", "zh": "牛奶在冰箱里。"}, {"id": "A1-14-03", "t": "pick", "p": "p2", "q": "Was ___ ihr trinken?", "a": "möchtet", "o": ["möchten", "möchtest"], "why": "ihr möchtet。", "zh": "你们想喝什么？"}, {"id": "A1-14-04", "t": "pick", "p": "p2", "q": "Sebastian ___ ein Bier.", "a": "möchte", "o": ["möchtest", "möchtet"], "why": "er möchte，没有 -t。", "zh": "Sebastian 想要一瓶啤酒。"}, {"id": "A1-14-05", "t": "fix", "p": "p2", "s": "Er möchtet einen Tee.", "bad": "möchtet", "a": "möchte", "o": ["möchtest", "möchten"], "why": "er / sie 用 möchte；möchtet 是 ihr 的形式。", "zh": "他想要一杯茶。"}, {"id": "A1-14-06", "t": "pick", "p": "p1", "q": "___ kennt Yaras Fahrradladen? – Niemand.", "a": "Wer", "o": ["Was", "Wie"], "why": "问“谁”用 wer。", "zh": "谁知道 Yara 的自行车店？——没人知道。"}]}, "A1-15": {"p": ["p3"], "items": [{"id": "A1-15-01", "t": "pick", "p": "p3", "q": "Was ___ du, Nico?", "a": "nimmst", "o": ["nehmst", "nimmt"], "why": "nehmen：du nimmst。", "zh": "Nico，你要什么？"}, {"id": "A1-15-02", "t": "pick", "p": "p3", "q": "Nina ___ gern Pizza Hawaii.", "a": "isst", "o": ["esst", "esse"], "why": "essen：er / sie isst。", "zh": "Nina 喜欢吃夏威夷比萨。"}, {"id": "A1-15-03", "t": "type", "p": "p3", "q": "Ich ___ eine Pizza mit Thunfisch.", "a": "nehme", "why": "ich 不换音：ich nehme。", "hint": "nehmen", "zh": "我要一个金枪鱼比萨。"}, {"id": "A1-15-04", "t": "fix", "p": "p3", "s": "Nawin esst gern Sushi.", "bad": "esst", "a": "isst", "o": ["esse", "essen"], "why": "er / sie 要换音：isst；esst 是 ihr 的形式。", "zh": "Nawin 喜欢吃寿司。"}, {"id": "A1-15-05", "t": "trans", "p": "p3", "src": "Ich esse gern Salat.", "cue": "换成 er", "q": "Er ___ gern Salat.", "a": "isst", "o": ["esst", "esse"], "why": "er isst。", "zh": "他喜欢吃沙拉。"}, {"id": "A1-15-06", "t": "sort", "p": "p3", "q": "哪些形式换了元音（e → i）？", "cats": ["换音了", "没换音"], "items": [{"w": "du nimmst", "c": 0}, {"w": "er isst", "c": 0}, {"w": "sie nimmt", "c": 0}, {"w": "ich nehme", "c": 1}, {"w": "wir essen", "c": 1}, {"w": "ihr esst", "c": 1}], "why": "只有 du 和 er / sie / es 换音，ich、wir、ihr、sie / Sie 不换。"}]}, "A1-16": {"p": ["p4"], "items": [{"id": "A1-16-01", "t": "pick", "p": "p4", "q": "___ viel kostet die Pizza?", "a": "Wie", "o": ["Was", "Wo"], "why": "Wie viel kostet …? 或 Was kostet …?", "zh": "这个比萨多少钱？"}, {"id": "A1-16-02", "t": "pick", "p": "p4", "q": "Das ___ zusammen 40,50 Euro.", "a": "macht", "o": ["hat", "gibt"], "why": "结账时说 Das macht (zusammen) …", "zh": "一共 40.50 欧元。"}, {"id": "A1-16-03", "t": "type", "p": "p4", "q": "听价格，写出来（例如 9,90）：___", "a": "22,50", "why": "zweiundzwanzig Euro fünfzig = 22,50 €。", "say": "zweiundzwanzig Euro fünfzig", "alt": ["22,50 €", "22,50€"]}, {"id": "A1-16-04", "t": "pick", "p": "p4", "q": "Zahlen Sie bar oder ___ Karte?", "a": "mit", "o": ["von", "in"], "why": "刷卡：mit Karte。", "zh": "您付现金还是刷卡？"}, {"id": "A1-16-05", "t": "fix", "p": "p4", "s": "Hier sind 45 Euros.", "bad": "Euros", "a": "Euro", "o": ["Eure", "Euren"], "why": "价格里的 Euro 不加复数 -s。", "zh": "这是 45 欧元。"}, {"id": "A1-16-06", "t": "order", "p": "p4", "tiles": ["die", "kostet", "Was", "Pizza"], "a": "Was kostet die Pizza?", "zh": "比萨多少钱？", "why": "W 问句：Was 第一，动词 kostet 第二。"}]}, "A1-17": {"p": ["p1", "p2"], "items": [{"id": "A1-17-01", "t": "pick", "p": "p1", "q": "Warst du schon mal in Berlin? – Ja, ich ___ schon mal in Berlin.", "a": "war", "o": ["bin", "warst"], "why": "说“去过”用过去时：ich war。", "zh": "你去过柏林吗？——去过。"}, {"id": "A1-17-02", "t": "pick", "p": "p1", "q": "Nawin ___ schon mal in Hamburg und in Köln.", "a": "war", "o": ["waren", "warst"], "why": "er war。", "zh": "Nawin 去过汉堡和科隆。"}, {"id": "A1-17-03", "t": "trans", "p": "p1", "src": "Bist du in Köln?", "cue": "改成过去时", "q": "___ du in Köln?", "a": "Warst", "o": ["War", "Wart"], "why": "bist → warst。", "zh": "你（当时）在科隆吗？"}, {"id": "A1-17-04", "t": "pick", "p": "p2", "q": "Wohin fährst du? – Ich fahre ___ Hamburg.", "a": "nach", "o": ["in", "aus"], "why": "Wohin? → nach + 城市。", "zh": "你去哪儿？——我去汉堡。"}, {"id": "A1-17-05", "t": "fix", "p": "p2", "s": "Der Kölner Dom ist nach Köln.", "bad": "nach", "a": "in", "o": ["aus", "von"], "why": "在某城市用 in；nach 表示去往。", "zh": "科隆大教堂在科隆。"}, {"id": "A1-17-06", "t": "type", "p": "p1", "q": "Wir ___ noch nie in Österreich.", "a": "waren", "why": "wir waren。", "hint": "sein 的过去时", "zh": "我们从没去过奥地利。"}]}, "A1-18": {"p": ["p2", "p3"], "items": [{"id": "A1-18-01", "t": "pick", "p": "p2", "q": "Spanien ist im Süden ___ Europa.", "a": "von", "o": ["aus", "in"], "why": "im Süden von …", "zh": "西班牙在欧洲南部。"}, {"id": "A1-18-02", "t": "pick", "p": "p2", "q": "Damaskus ist im ___ von Syrien.", "a": "Süden", "o": ["Süd", "südlich"], "why": "im Süden von …：在……的南部。", "zh": "大马士革在叙利亚南部。"}, {"id": "A1-18-03", "t": "order", "p": "p3", "tiles": ["du", "aus", "Kommst", "Italien"], "a": "Kommst du aus Italien?", "zh": "你来自意大利吗？", "why": "是非问句：变位动词第一。"}, {"id": "A1-18-04", "t": "order", "p": "p3", "tiles": ["Spanien", "komme", "aus", "Ich"], "a": "Ich komme aus Spanien.", "zh": "我来自西班牙。", "why": "陈述句：动词第二。", "alt": ["Aus Spanien komme ich."]}, {"id": "A1-18-05", "t": "pick", "p": "p3", "q": "哪一句是是非问句（用 ja / nein 回答）？___", "a": "Spricht Selma Deutsch?", "o": ["Woher kommt Selma?", "Selma spricht Deutsch."], "why": "是非问句的动词在第一位。"}, {"id": "A1-18-06", "t": "trans", "p": "p3", "src": "Selma kommt aus Syrien.", "cue": "改成是非问句", "q": "___ Selma aus Syrien?", "a": "Kommt", "o": ["Kommst", "Komme"], "why": "动词放第一位，形式不变：kommt。", "zh": "Selma 来自叙利亚吗？"}]}, "A1-19": {"p": ["p3", "p4"], "items": [{"id": "A1-19-01", "t": "pick", "p": "p4", "q": "In Japan ___ man Sushi.", "a": "isst", "o": ["esst", "essen"], "why": "man isst。", "zh": "在日本人们吃寿司。"}, {"id": "A1-19-02", "t": "pick", "p": "p3", "q": "___ isst man in Frankreich? – Käse.", "a": "Was", "o": ["Wer", "Wo"], "why": "问东西用 was。", "zh": "在法国人们吃什么？——奶酪。"}, {"id": "A1-19-03", "t": "order", "p": "p3", "tiles": ["isst", "In", "Pizza", "man", "Italien"], "a": "In Italien isst man Pizza.", "zh": "在意大利人们吃比萨。", "why": "地点放句首，动词仍在第二位。", "alt": ["Man isst in Italien Pizza.", "Pizza isst man in Italien."]}, {"id": "A1-19-04", "t": "fix", "p": "p4", "s": "In Spanien isst Mann Gazpacho.", "bad": "Mann", "a": "man", "o": ["Man", "men"], "why": "“人们”是 man（小写、一个 n）。", "zh": "在西班牙人们吃西班牙冷汤。"}, {"id": "A1-19-05", "t": "trans", "p": "p3", "src": "Ich fahre nächstes Jahr nach Norwegen.", "cue": "把 Nächstes Jahr 放到句首", "q": "Nächstes Jahr ___ ich nach Norwegen.", "a": "fahre", "o": ["fahren", "fahrt"], "why": "动词仍在第二位，形式不变：fahre。", "zh": "明年我去挪威。"}, {"id": "A1-19-06", "t": "pick", "p": "p2", "q": "Sushi isst man ___ Japan.", "a": "in", "o": ["nach", "aus"], "why": "在某个国家：in + 国家。", "zh": "在日本人们吃寿司。"}]}, "A1-20": {"p": ["p4", "p1"], "items": [{"id": "A1-20-01", "t": "pick", "p": "p4", "q": "Welche Sprachen sprichst du? – Ich ___ Spanisch und ein bisschen Deutsch.", "a": "spreche", "o": ["sprichst", "spricht"], "why": "ich 不换音：ich spreche。", "zh": "你会说哪些语言？——西班牙语和一点德语。"}, {"id": "A1-20-02", "t": "pick", "p": "p4", "q": "Selma ___ sehr gut Deutsch.", "a": "spricht", "o": ["sprecht", "sprichst"], "why": "er / sie spricht。", "zh": "Selma 德语说得很好。"}, {"id": "A1-20-03", "t": "type", "p": "p4", "q": "___ du Englisch?", "a": "Sprichst", "why": "du sprichst；是非问句动词在第一位。", "hint": "sprechen", "zh": "你会说英语吗？"}, {"id": "A1-20-04", "t": "pick", "p": "p1", "q": "___ die Party gut?", "a": "War", "o": ["Warst", "Waren"], "why": "die Party 是单数：war。", "zh": "派对好玩吗？"}, {"id": "A1-20-05", "t": "fix", "p": "p1", "s": "Die Party waren super!", "bad": "waren", "a": "war", "o": ["warst", "wart"], "why": "die Party 是单数，用 war。", "zh": "派对太棒了！"}, {"id": "A1-20-06", "t": "sort", "p": "p4", "q": "哪些形式换了元音（e → i）？", "cats": ["换音了", "没换音"], "items": [{"w": "du sprichst", "c": 0}, {"w": "sie spricht", "c": 0}, {"w": "ich spreche", "c": 1}, {"w": "wir sprechen", "c": 1}], "why": "sprechen 和 essen、nehmen 一样，只在 du 和 er / sie 时换音。"}]}, "A1-21": {"p": ["p1"], "items": [{"id": "A1-21-01", "t": "pick", "p": "p1", "q": "___ Buch ist hier.", "a": "Das", "o": ["Der", "Die"], "why": "das Buch 是中性。", "zh": "书在这儿。"}, {"id": "A1-21-02", "t": "pick", "p": "p1", "q": "Wo sind ___ Bücher?", "a": "die", "o": ["das", "der"], "why": "复数一律 die。", "zh": "书在哪儿？"}, {"id": "A1-21-03", "t": "type", "p": "p1", "q": "der Stift → die ___", "a": "Stifte", "why": "Stift 的复数加 -e：Stifte。", "hint": "复数"}, {"id": "A1-21-04", "t": "fix", "p": "p1", "s": "Wo ist der Brille?", "bad": "der", "a": "die", "o": ["das", "den"], "why": "die Brille 是阴性。", "zh": "眼镜在哪儿？"}, {"id": "A1-21-05", "t": "pick", "p": "p1", "q": "Lisa sucht ___ Brille, die Stifte und das Buch.", "a": "die", "o": ["der", "das"], "why": "die Brille。", "zh": "Lisa 在找眼镜、笔和书。"}, {"id": "A1-21-06", "t": "sort", "p": "p1", "q": "按冠词分类", "cats": ["der", "die", "das"], "items": [{"w": "Bleistift", "c": 0}, {"w": "Radiergummi", "c": 0}, {"w": "Brille", "c": 1}, {"w": "Sprachschule", "c": 1}, {"w": "Buch", "c": 2}, {"w": "Papier", "c": 2}], "why": "der Bleistift、der Radiergummi · die Brille、die Sprachschule · das Buch、das Papier"}]}, "A1-22": {"p": ["p1", "p2"], "items": [{"id": "A1-22-01", "t": "pick", "p": "p2", "q": "Was ist das? – Das ist ___ Tafel.", "a": "eine", "o": ["ein", "einen"], "why": "die Tafel，不特指 → eine Tafel。", "zh": "这是什么？——这是一块黑板。"}, {"id": "A1-22-02", "t": "pick", "p": "p2", "q": "Das ist ___ Wörterbuch.", "a": "ein", "o": ["eine", "einen"], "why": "das Wörterbuch 是中性 → ein。", "zh": "这是一本词典。"}, {"id": "A1-22-03", "t": "fix", "p": "p1", "s": "Der Tafel ist groß.", "bad": "Der", "a": "Die", "o": ["Das", "Den"], "why": "die Tafel 是阴性。", "zh": "黑板很大。"}, {"id": "A1-22-04", "t": "type", "p": "p1", "q": "das Wort → die ___", "a": "Wörter", "why": "Wort 的复数加 -er 并变音：Wörter。", "hint": "复数"}, {"id": "A1-22-05", "t": "pick", "p": "p2", "q": "Das ist eine Tasche. Und das hier ist ___ Tasche von Jenny.（特指 Jenny 的那一个）", "a": "die", "o": ["eine", "ein"], "why": "特指、知道属于谁时用定冠词。", "zh": "这是一个包。这个是 Jenny 的包。"}, {"id": "A1-22-06", "t": "order", "p": "p1", "tiles": ["gehören", "Nomen", "Artikel", "und", "zusammen", "immer"], "a": "Nomen und Artikel gehören immer zusammen.", "zh": "名词和冠词永远是一起的。", "why": "陈述句：动词 gehören 在第二位（第一位是 Nomen und Artikel 这一整组）。", "alt": ["Artikel und Nomen gehören immer zusammen."]}]}, "A1-23": {"p": ["p3"], "items": [{"id": "A1-23-01", "t": "pick", "p": "p3", "q": "Ich brauche ___ Zettel.", "a": "einen", "o": ["ein", "eine"], "why": "der Zettel 是宾语 → einen。", "zh": "我需要一张纸条。"}, {"id": "A1-23-02", "t": "pick", "p": "p3", "q": "Wir suchen ___ Mieter.", "a": "einen", "o": ["ein", "eine"], "why": "der Mieter 是宾语 → einen。", "zh": "我们在找租客。"}, {"id": "A1-23-03", "t": "pick", "p": "p3", "q": "Die Wohnung hat ___ Terrasse.", "a": "eine", "o": ["einen", "ein"], "why": "die Terrasse 是阴性，第四格不变：eine。", "zh": "公寓有个露台。"}, {"id": "A1-23-04", "t": "fix", "p": "p3", "s": "Im Haus ist keinen Aufzug.", "bad": "keinen", "a": "kein", "o": ["keine", "keiner"], "why": "Aufzug 在这里是主语（第一格）→ kein。", "zh": "楼里没有电梯。"}, {"id": "A1-23-05", "t": "trans", "p": "p3", "src": "Ich habe einen Stift.", "cue": "改成否定", "q": "Ich habe ___ Stift.", "a": "keinen", "o": ["kein", "nicht"], "why": "阳性宾语：einen → keinen。", "zh": "我没有笔。"}, {"id": "A1-23-06", "t": "pick", "p": "p3", "q": "Wir haben ___ Garage.（没有）", "a": "keine", "o": ["keinen", "kein"], "why": "die Garage 是阴性 → keine。", "zh": "我们没有车库。"}]}, "A1-24": {"p": ["p4"], "items": [{"id": "A1-24-01", "t": "pick", "p": "p4", "q": "alt ↔ ___", "a": "neu", "o": ["rot", "groß"], "why": "alt（旧）的反义词是 neu（新）。"}, {"id": "A1-24-02", "t": "pick", "p": "p4", "q": "Das Auto ist ___.（红色的）", "a": "rot", "o": ["Rot", "rote"], "why": "sein + 形容词原形，小写。", "zh": "这辆车是红色的。"}, {"id": "A1-24-03", "t": "fix", "p": "p4", "s": "Das Auto ist nicht groß, es ist kleines.", "bad": "kleines", "a": "klein", "o": ["Klein", "kleine"], "why": "sein 后面的形容词不加词尾。", "zh": "这辆车不大，是小的。"}, {"id": "A1-24-04", "t": "type", "p": "p4", "q": "Das T-Shirt ist ___.", "a": "weiß", "why": "sein + 形容词原形。", "hint": "白色的", "zh": "这件 T 恤是白色的。"}, {"id": "A1-24-05", "t": "order", "p": "p4", "tiles": ["ist", "Das", "gelb", "Haus"], "a": "Das Haus ist gelb.", "zh": "这栋房子是黄色的。", "why": "主语 + sein + 形容词。", "alt": ["Gelb ist das Haus."]}, {"id": "A1-24-06", "t": "sort", "p": "p4", "q": "描述大小还是颜色？", "cats": ["大小", "颜色"], "items": [{"w": "groß", "c": 0}, {"w": "klein", "c": 0}, {"w": "rot", "c": 1}, {"w": "gelb", "c": 1}, {"w": "weiß", "c": 1}], "why": "groß、klein 说大小；rot、gelb、weiß 是颜色。"}]}, "A1-25": {"p": ["p1"], "items": [{"id": "A1-25-01", "t": "pick", "p": "p1", "q": "Das ist ___ Auto von Lisa.（特指）", "a": "das", "o": ["ein", "kein"], "why": "知道是谁的 → 定冠词。", "zh": "这是 Lisa 的车。"}, {"id": "A1-25-02", "t": "pick", "p": "p1", "q": "Das ist ___ Jugendherberge.（不特指）", "a": "eine", "o": ["ein", "einen"], "why": "die Jugendherberge → eine。", "zh": "这是一家青年旅舍。"}, {"id": "A1-25-03", "t": "fix", "p": "p1", "s": "Ich suche einen Hostel.", "bad": "einen", "a": "ein", "o": ["eine", "einem"], "why": "das Hostel 是中性，第四格不变：ein Hostel。", "zh": "我在找一家青旅。"}, {"id": "A1-25-04", "t": "pick", "p": "p1", "q": "Hier gibt es ___ Garten.（没有）", "a": "keinen", "o": ["kein", "nicht"], "why": "es gibt 后面是第四格；der Garten → keinen。", "zh": "这里没有花园。"}, {"id": "A1-25-05", "t": "sort", "p": "p1", "q": "第一格还是第四格？", "cats": ["第一格", "第四格"], "items": [{"w": "ein Balkon", "c": 0}, {"w": "kein Garten", "c": 0}, {"w": "der Keller", "c": 0}, {"w": "einen Balkon", "c": 1}, {"w": "keinen Garten", "c": 1}, {"w": "den Keller", "c": 1}], "why": "阳性第四格：der → den，ein → einen，kein → keinen。"}, {"id": "A1-25-06", "t": "trans", "p": "p1", "src": "Das ist ein Hotel.", "cue": "改成否定", "q": "Das ist ___ Hotel.", "a": "kein", "o": ["nicht", "keine"], "why": "ein Hotel → kein Hotel。", "zh": "这不是酒店。"}]}, "A1-26": {"p": ["p2"], "items": [{"id": "A1-26-01", "t": "pick", "p": "p2", "q": "Das Bad ist ___ hell, es ist dunkel.", "a": "nicht", "o": ["kein", "keine"], "why": "否定形容词用 nicht。", "zh": "浴室不亮，很暗。"}, {"id": "A1-26-02", "t": "order", "p": "p2", "tiles": ["ist", "nicht", "Die", "laut", "Küche"], "a": "Die Küche ist nicht laut.", "zh": "厨房不吵。", "why": "nicht 放在形容词前。"}, {"id": "A1-26-03", "t": "trans", "p": "p2", "src": "Das Zimmer ist ruhig.", "cue": "改成否定", "q": "Das Zimmer ist ___ ruhig.", "a": "nicht", "o": ["kein", "keine"], "why": "形容词用 nicht 否定。", "zh": "房间不安静。"}, {"id": "A1-26-04", "t": "fix", "p": "p2", "s": "Das Wohnzimmer ist kein gemütlich.", "bad": "kein", "a": "nicht", "o": ["keine", "nichts"], "why": "gemütlich 是形容词，用 nicht。", "zh": "客厅不舒适。"}, {"id": "A1-26-05", "t": "pick", "p": "p2", "q": "Hier ist ___ Toilette.（没有厕所）", "a": "keine", "o": ["nicht", "kein"], "why": "否定名词用 kein；die Toilette → keine。", "zh": "这里没有厕所。"}, {"id": "A1-26-06", "t": "sort", "p": "p2", "q": "用 nicht 还是 kein？", "cats": ["nicht", "kein"], "items": [{"w": "groß", "c": 0}, {"w": "hell", "c": 0}, {"w": "ruhig", "c": 0}, {"w": "Balkon", "c": 1}, {"w": "Küche", "c": 1}, {"w": "Fenster", "c": 1}], "why": "形容词用 nicht，名词用 kein。"}]}, "A1-27": {"p": ["p3"], "items": [{"id": "A1-27-01", "t": "pick", "p": "p3", "q": "Die Stühle sind alt und der Schrank ist viel ___ groß.", "a": "zu", "o": ["sehr", "so"], "why": "viel zu groß = 实在太大了。", "zh": "椅子旧了，柜子也太大了。"}, {"id": "A1-27-02", "t": "pick", "p": "p3", "q": "der Schreibtisch + der Stuhl → ___ Schreibtischstuhl", "a": "der", "o": ["das", "die"], "why": "看最后一个词：der Stuhl。", "zh": "书桌椅"}, {"id": "A1-27-03", "t": "pick", "p": "p3", "q": "das Bad + das Zimmer → ___ Badezimmer", "a": "das", "o": ["der", "die"], "why": "看最后一个词：das Zimmer。", "zh": "浴室"}, {"id": "A1-27-04", "t": "type", "p": "p3", "q": "die Kleider + der Schrank → der ___", "a": "Kleiderschrank", "why": "直接连写：der Kleiderschrank。", "hint": "复合词"}, {"id": "A1-27-05", "t": "fix", "p": "p3", "s": "Der Bücherregal ist voll.", "bad": "Der", "a": "Das", "o": ["Die", "Den"], "why": "das Regal → das Bücherregal。", "zh": "书架满了。"}, {"id": "A1-27-06", "t": "trans", "p": "p3", "src": "Der Tisch ist groß.", "cue": "改成“太大了”", "q": "Der Tisch ist ___ groß.", "a": "zu", "o": ["sehr", "viel"], "why": "太……：zu + 形容词。", "zh": "桌子太大了。"}]}, "A1-28": {"p": ["p4"], "items": [{"id": "A1-28-01", "t": "pick", "p": "p4", "q": "Ulla: Ist das ___ Bad?（我的）", "a": "mein", "o": ["meine", "meinen"], "why": "das Bad 是中性 → mein。", "zh": "这是我的浴室吗？"}, {"id": "A1-28-02", "t": "pick", "p": "p4", "q": "Nein, wir haben nur ein Bad. Das ist ___ Bad.（我们的）", "a": "unser", "o": ["unsere", "euer"], "why": "wir → unser。", "zh": "不，我们只有一个浴室。这是我们的浴室。"}, {"id": "A1-28-03", "t": "pick", "p": "p4", "q": "Nawin, ist das ___ Unterhose?（你的）", "a": "deine", "o": ["dein", "deinen"], "why": "die Unterhose 是阴性 → deine。", "zh": "Nawin，这是你的内裤吗？"}, {"id": "A1-28-04", "t": "fix", "p": "p4", "s": "Lisa sucht seine Brille.", "bad": "seine", "a": "ihre", "o": ["ihr", "seiner"], "why": "Lisa 是女性 → ihre；die Brille 是阴性加 -e。", "zh": "Lisa 在找她的眼镜。"}, {"id": "A1-28-05", "t": "sort", "p": "p4", "q": "用 sein(e) 还是 ihr(e)？", "cats": ["sein(e)（他的）", "ihr(e)（她的）"], "items": [{"w": "Nicos Pass", "c": 0}, {"w": "Sebastians Föhn", "c": 0}, {"w": "Nawins Zimmer", "c": 0}, {"w": "Lisas Brille", "c": 1}, {"w": "Emmas Zimmer", "c": 1}, {"w": "Ninas Getränk", "c": 1}], "why": "东西属于男人用 sein，属于女人用 ihr。"}, {"id": "A1-28-06", "t": "type", "p": "p4", "q": "Ihr putzt nie! Das ist ___ Bad!", "a": "euer", "why": "ihr（你们）→ euer；das Bad 不加 -e。", "hint": "你们的", "zh": "你们从来不打扫！这是你们的浴室！"}]}, "A1-29": {"p": ["p1", "p2"], "items": [{"id": "A1-29-01", "t": "pick", "p": "p1", "q": "14:30 → Es ist halb ___.", "a": "drei", "o": ["zwei", "vierzehn"], "why": "14:30 = 2:30，下一个整点是 3：halb drei。"}, {"id": "A1-29-02", "t": "pick", "p": "p2", "q": "___ beginnt der Kurs? – Um neun.", "a": "Wann", "o": ["Wo", "Wie"], "why": "问时间用 Wann。", "zh": "课什么时候开始？——九点。"}, {"id": "A1-29-03", "t": "pick", "p": "p2", "q": "Das Training ist ___ zwei bis vier.", "a": "von", "o": ["um", "am"], "why": "一段时间：von … bis。", "zh": "训练是两点到四点。"}, {"id": "A1-29-04", "t": "type", "p": "p1", "q": "听时间，写数字（例如 9:00）：___", "a": "12:00", "why": "zwölf Uhr mittags = 12:00。", "say": "Es ist zwölf Uhr mittags.", "alt": ["12", "12 Uhr", "12.00"]}, {"id": "A1-29-05", "t": "fix", "p": "p2", "s": "Nina hat am acht einen Termin beim Arzt.", "bad": "am", "a": "um", "o": ["im", "von"], "why": "几点钟用 um。", "zh": "Nina 八点有个看医生的预约。"}, {"id": "A1-29-06", "t": "order", "p": "p2", "tiles": ["arbeite", "Ich", "acht", "bis", "von", "zwölf"], "a": "Ich arbeite von acht bis zwölf.", "zh": "我从八点工作到十二点。", "why": "von … bis 说一段时间。", "alt": ["Von acht bis zwölf arbeite ich."]}]}, "A1-30": {"p": ["p3"], "items": [{"id": "A1-30-01", "t": "pick", "p": "p3", "q": "Wann stehst du ___?", "a": "auf", "o": ["an", "aus"], "why": "aufstehen：前缀 auf 放句尾。", "zh": "你几点起床？"}, {"id": "A1-30-02", "t": "pick", "p": "p3", "q": "Nach dem Spielen ___ Emma auf.", "a": "räumt", "o": ["aufräumt", "räumen"], "why": "可分动词拆开：räumt … auf。", "zh": "玩完以后 Emma 收拾。"}, {"id": "A1-30-03", "t": "trans", "p": "p3", "src": "Ich rufe Lisa an.", "cue": "换成 er", "q": "Er ___ Lisa an.", "a": "ruft", "o": ["anruft", "rufst"], "why": "anrufen 拆开：er ruft … an。", "zh": "他给 Lisa 打电话。"}, {"id": "A1-30-04", "t": "order", "p": "p3", "tiles": ["sieht", "Emma", "nicht", "fern"], "a": "Emma sieht nicht fern.", "zh": "Emma 不看电视。", "why": "sieht 第二位，nicht 在前缀 fern 前面，fern 放句尾。"}, {"id": "A1-30-05", "t": "pick", "p": "p3", "q": "Emma isst ___ einen Apfel.（有时候）", "a": "manchmal", "o": ["immer", "nie"], "why": "有时候 = manchmal。", "zh": "Emma 有时吃一个苹果。"}, {"id": "A1-30-06", "t": "sort", "p": "p3", "q": "可分还是不可分？", "cats": ["可分动词", "不可分动词"], "items": [{"w": "aufstehen", "c": 0}, {"w": "fernsehen", "c": 0}, {"w": "einkaufen", "c": 0}, {"w": "verkaufen", "c": 1}, {"w": "besuchen", "c": 1}, {"w": "verstehen", "c": 1}], "why": "auf-、fern-、ein- 可分；ver-、be- 不可分。"}]}, "A1-31": {"p": ["p2"], "items": [{"id": "A1-31-01", "t": "pick", "p": "p2", "q": "___ Montag spiele ich mit Tante Lisa Fußball.", "a": "Am", "o": ["Um", "Im"], "why": "星期几用 am。", "zh": "星期一我和 Lisa 阿姨踢足球。"}, {"id": "A1-31-02", "t": "pick", "p": "p2", "q": "Am Dienstag ___ ich zum Musikkurs.", "a": "gehe", "o": ["gehst", "geht"], "why": "时间放句首，动词仍在第二位：gehe ich。", "zh": "星期二我去音乐课。"}, {"id": "A1-31-03", "t": "order", "p": "p2", "tiles": ["wasche", "Am", "ich", "Mittwoch", "Auto", "das"], "a": "Am Mittwoch wasche ich das Auto.", "zh": "星期三我洗车。", "why": "时间放句首，动词第二，主语第三。", "alt": ["Ich wasche am Mittwoch das Auto."]}, {"id": "A1-31-04", "t": "fix", "p": "p2", "s": "Im Freitag sieht Emma fern.", "bad": "Im", "a": "Am", "o": ["Um", "An"], "why": "星期几用 am。", "zh": "星期五 Emma 看电视。"}, {"id": "A1-31-05", "t": "pick", "p": "p2", "q": "Wann kochst du? – ___ Sonntag.", "a": "Am", "o": ["Um", "In"], "why": "星期几用 am。", "zh": "你什么时候做饭？——星期天。"}, {"id": "A1-31-06", "t": "type", "p": "p2", "q": "___ neun Uhr beginnt der Kurs.", "a": "Um", "why": "具体时刻用 um。", "hint": "时刻的介词", "zh": "九点开始上课。"}]}, "A1-32": {"p": ["p4"], "items": [{"id": "A1-32-01", "t": "pick", "p": "p4", "q": "（首先）___ machen wir die Hausaufgaben, dann räumen wir auf.", "a": "Zuerst", "o": ["Danach", "Gestern"], "why": "首先 = zuerst。", "zh": "我们先做作业，然后收拾。"}, {"id": "A1-32-02", "t": "pick", "p": "p4", "q": "Fährst du nach Berlin? – Nein, ich ___ nach München.", "a": "fahre", "o": ["fährst", "fährt"], "why": "ich 不换音：ich fahre。", "zh": "你去柏林吗？——不，我去慕尼黑。"}, {"id": "A1-32-03", "t": "pick", "p": "p4", "q": "Wann ___ der Film an?", "a": "fängt", "o": ["fangt", "fängst"], "why": "anfangen 换音并拆开：der Film fängt … an。", "zh": "电影什么时候开始？"}, {"id": "A1-32-04", "t": "type", "p": "p4", "q": "Emma ___ lange.", "a": "schläft", "why": "er / sie schläft（a → ä）。", "hint": "schlafen", "zh": "Emma 睡得很久。"}, {"id": "A1-32-05", "t": "order", "p": "p4", "tiles": ["essen", "Danach", "wir", "Eis"], "a": "Danach essen wir Eis.", "zh": "然后我们吃冰淇淋。", "why": "danach 放句首，动词 essen 第二。", "alt": ["Wir essen danach Eis."]}, {"id": "A1-32-06", "t": "fix", "p": "p4", "s": "Lisa fahrt mit dem Auto.", "bad": "fahrt", "a": "fährt", "o": ["fährst", "fahre"], "why": "er / sie 要换音：fährt；fahrt 是 ihr 的形式。", "zh": "Lisa 开车去。"}]}, "A1-33": {"p": ["p1"], "items": [{"id": "A1-33-01", "t": "pick", "p": "p1", "q": "12:30 → Es ist ___ eins.", "a": "halb", "o": ["Viertel", "kurz"], "why": "12:30 = halb eins。"}, {"id": "A1-33-02", "t": "pick", "p": "p1", "q": "Kommt sie um Viertel ___ zwölf?（12:15）", "a": "nach", "o": ["vor", "halb"], "why": "12:15 = Viertel nach zwölf。", "zh": "她十二点一刻来吗？"}, {"id": "A1-33-03", "t": "pick", "p": "p1", "q": "（正式）Wir haben von neun bis ___ Uhr geöffnet.（23:00）", "a": "dreiundzwanzig", "o": ["zweiunddreißig", "dreizehn"], "why": "正式说法用 24 小时制：dreiundzwanzig Uhr。", "zh": "我们从九点营业到二十三点。"}, {"id": "A1-33-04", "t": "type", "p": "p1", "q": "听时间，写数字：___", "a": "12:15", "why": "Viertel nach zwölf = 12:15。", "say": "Es ist Viertel nach zwölf.", "alt": ["12.15"]}, {"id": "A1-33-05", "t": "pick", "p": "p1", "q": "Wie ___ Uhr ist es?", "a": "viel", "o": ["viele", "spät"], "why": "问几点：Wie viel Uhr ist es?（或 Wie spät ist es?）", "zh": "现在几点？"}, {"id": "A1-33-06", "t": "sort", "p": "p1", "q": "正式说法还是日常说法？", "cats": ["正式说法", "日常说法"], "items": [{"w": "siebzehn Uhr vierzig", "c": 0}, {"w": "zwölf Uhr fünfzehn", "c": 0}, {"w": "neunzehn Uhr dreißig", "c": 0}, {"w": "zwanzig vor sechs", "c": 1}, {"w": "Viertel nach zwölf", "c": 1}, {"w": "halb acht", "c": 1}], "why": "正式说法：24 小时制、先小时后分钟；日常说法：Viertel、halb、vor / nach。"}]}, "A1-34": {"p": ["p2"], "items": [{"id": "A1-34-01", "t": "pick", "p": "p2", "q": "Morgen ist der ___.（22.）", "a": "Zweiundzwanzigste", "o": ["Zweiundzwanzigte", "Zweiundzwanzig"], "why": "20 以上加 -ste。", "zh": "明天是二十二号。"}, {"id": "A1-34-02", "t": "pick", "p": "p2", "q": "Vom ersten bis zum ___ November.（7.）", "a": "siebten", "o": ["siebzehnten", "sieben"], "why": "zum 后面加 -en：zum siebten。", "zh": "十一月一号到七号。"}, {"id": "A1-34-03", "t": "type", "p": "p2", "q": "Heute ist der ___ Mai.（3.）", "a": "dritte", "why": "3 的序数词：dritte。", "hint": "序数词", "zh": "今天是五月三号。"}, {"id": "A1-34-04", "t": "pick", "p": "p2", "q": "___ Wievielte ist heute?", "a": "Der", "o": ["Die", "Das"], "why": "问日期：Der Wievielte ist heute?", "zh": "今天几号？"}, {"id": "A1-34-05", "t": "fix", "p": "p2", "s": "Heute ist der zwanzigte April.", "bad": "zwanzigte", "a": "zwanzigste", "o": ["zwanzig", "zwanzigeste"], "why": "20 以上加 -ste。", "zh": "今天是四月二十号。"}, {"id": "A1-34-06", "t": "sort", "p": "p2", "q": "加 -te 还是 -ste？", "cats": ["-te", "-ste"], "items": [{"w": "zweite", "c": 0}, {"w": "vierte", "c": 0}, {"w": "neunzehnte", "c": 0}, {"w": "zwanzigste", "c": 1}, {"w": "einundzwanzigste", "c": 1}, {"w": "dreißigste", "c": 1}], "why": "1–19 加 -te，20 以上加 -ste。"}]}, "A1-35": {"p": ["p3"], "items": [{"id": "A1-35-01", "t": "pick", "p": "p3", "q": "Diese Woche ___ ich nicht.", "a": "kann", "o": ["kannst", "können"], "why": "ich kann。", "zh": "这周我不行。"}, {"id": "A1-35-02", "t": "pick", "p": "p3", "q": "Wann ___ ihr Fußball spielen?", "a": "könnt", "o": ["kannst", "können"], "why": "ihr könnt。", "zh": "你们什么时候能踢球？"}, {"id": "A1-35-03", "t": "pick", "p": "p3", "q": "Samstag geht nicht. ___ du am Freitag?", "a": "Kannst", "o": ["Kann", "Können"], "why": "du kannst；是非问句动词第一。", "zh": "星期六不行。你星期五可以吗？"}, {"id": "A1-35-04", "t": "pick", "p": "p3", "q": "Ich habe ___ Monat Zeit.（下个月）", "a": "nächsten", "o": ["nächste", "nächstes"], "why": "der Monat → nächsten Monat（第四格）。", "zh": "我下个月有空。"}, {"id": "A1-35-05", "t": "fix", "p": "p3", "s": "Nächstes Woche geht's.", "bad": "Nächstes", "a": "Nächste", "o": ["Nächsten", "Nächster"], "why": "die Woche → nächste Woche。", "zh": "下周可以。"}, {"id": "A1-35-06", "t": "order", "p": "p3", "tiles": ["du", "Kannst", "Montag", "am"], "a": "Kannst du am Montag?", "zh": "你星期一可以吗？", "why": "是非问句：情态动词 kannst 第一。"}]}, "A1-36": {"p": ["p4"], "items": [{"id": "A1-36-01", "t": "pick", "p": "p4", "q": "Wir ___ gestern keine Zeit.", "a": "hatten", "o": ["hattet", "hatte"], "why": "wir hatten。", "zh": "我们昨天没空。"}, {"id": "A1-36-02", "t": "pick", "p": "p4", "q": "___ du gestern Zeit?", "a": "Hattest", "o": ["Hatte", "Hattet"], "why": "du hattest。", "zh": "你昨天有空吗？"}, {"id": "A1-36-03", "t": "trans", "p": "p4", "src": "Ich habe eine Panne.", "cue": "改成过去时", "q": "Ich ___ eine Panne.", "a": "hatte", "o": ["hattest", "habe"], "why": "ich habe → ich hatte。", "zh": "我（的车）出故障了。"}, {"id": "A1-36-04", "t": "fix", "p": "p4", "s": "Lisa hattet Verspätung.", "bad": "hattet", "a": "hatte", "o": ["hattest", "hatten"], "why": "er / sie hatte；hattet 是 ihr 的形式。", "zh": "Lisa 迟到了。"}, {"id": "A1-36-05", "t": "pick", "p": "p4", "q": "Ich ___ eine halbe Stunde im Stau.", "a": "war", "o": ["hatte", "bin"], "why": "“在堵车中”说的是状态 / 位置 → war。", "zh": "我堵了半个小时。"}, {"id": "A1-36-06", "t": "sort", "p": "p4", "q": "用 war 还是 hatte？", "cats": ["war（sein）", "hatte（haben）"], "items": [{"w": "im Stau", "c": 0}, {"w": "zu spät", "c": 0}, {"w": "in Berlin", "c": 0}, {"w": "eine Panne", "c": 1}, {"w": "Verspätung", "c": 1}, {"w": "keine Zeit", "c": 1}], "why": "在哪里 / 怎么样用 war；有 / 遇到什么用 hatte。"}]}, "A1-37": {"p": ["p1"], "items": [{"id": "A1-37-01", "t": "pick", "p": "p1", "q": "der Koch → die ___", "a": "Köchin", "o": ["Kochin", "Köche"], "why": "Koch 变女性时变音：Köchin。"}, {"id": "A1-37-02", "t": "pick", "p": "p1", "q": "der Anwalt → die ___", "a": "Anwältin", "o": ["Anwaltin", "Anwälte"], "why": "Anwalt → Anwältin（变音）。"}, {"id": "A1-37-03", "t": "pick", "p": "p1", "q": "Ich bin ___ für Deutsch und Englisch.", "a": "Lehrerin", "o": ["eine Lehrerin", "die Lehrerin"], "why": "说职业不加冠词。", "zh": "我是德语和英语老师。"}, {"id": "A1-37-04", "t": "type", "p": "p1", "q": "der Ingenieur → die ___", "a": "Ingenieurin", "why": "加 -in。", "hint": "女性"}, {"id": "A1-37-05", "t": "fix", "p": "p1", "s": "Sie ist Friseur von Beruf.", "bad": "Friseur", "a": "Friseurin", "o": ["Friseure", "Friseurinnen"], "why": "说女性时用 Friseurin。", "zh": "她是理发师。"}, {"id": "A1-37-06", "t": "sort", "p": "p1", "q": "男性职业还是女性职业？", "cats": ["男性", "女性"], "items": [{"w": "Elektriker", "c": 0}, {"w": "Informatiker", "c": 0}, {"w": "Bankkaufmann", "c": 0}, {"w": "Bankkauffrau", "c": 1}, {"w": "Chefin", "c": 1}, {"w": "Kollegin", "c": 1}], "why": "-in 结尾的是女性；Bankkaufmann / Bankkauffrau 用 -mann / -frau 区分。"}]}, "A1-38": {"p": ["p2"], "items": [{"id": "A1-38-01", "t": "pick", "p": "p2", "q": "Was ___ ein Bankkaufmann machen?", "a": "muss", "o": ["musst", "müssen"], "why": "er muss。", "zh": "银行职员要做什么？"}, {"id": "A1-38-02", "t": "pick", "p": "p2", "q": "Du ___ E-Mails schreiben.", "a": "musst", "o": ["muss", "müsst"], "why": "du musst。", "zh": "你得写电子邮件。"}, {"id": "A1-38-03", "t": "order", "p": "p2", "tiles": ["Geld", "Ein", "muss", "zählen", "Bankkaufmann"], "a": "Ein Bankkaufmann muss Geld zählen.", "zh": "银行职员得数钱。", "why": "情态动词第二位，原形 zählen 放句尾。"}, {"id": "A1-38-04", "t": "trans", "p": "p2", "src": "Ich arbeite morgen.", "cue": "加上 müssen", "q": "Ich muss morgen ___.", "a": "arbeiten", "o": ["arbeite", "arbeitet"], "why": "情态动词后用原形，放句尾。", "zh": "我明天得工作。"}, {"id": "A1-38-05", "t": "fix", "p": "p2", "s": "Er muss Termine organisiert.", "bad": "organisiert", "a": "organisieren", "o": ["organisiere", "organisierst"], "why": "情态动词后面用原形。", "zh": "他得安排预约。"}, {"id": "A1-38-06", "t": "pick", "p": "p2", "q": "___ du gut kochen?", "a": "Kannst", "o": ["Kann", "Könnt"], "why": "du kannst；是非问句情态动词第一。", "zh": "你很会做饭吗？"}]}, "A1-39": {"p": ["p3"], "items": [{"id": "A1-39-01", "t": "pick", "p": "p3", "q": "Die Cafeteria ist in ___ dritten Etage.", "a": "der", "o": ["die", "dem"], "why": "die Etage，第三格 → der。", "zh": "咖啡厅在第三层。"}, {"id": "A1-39-02", "t": "pick", "p": "p3", "q": "Das Bewerbungsgespräch ist ___ Konferenzraum.", "a": "im", "o": ["in der", "in die"], "why": "der Konferenzraum，第三格 → in dem = im。", "zh": "面试在会议室。"}, {"id": "A1-39-03", "t": "pick", "p": "p3", "q": "Wo ist der Aufzug? – Neben ___ Treppe.", "a": "der", "o": ["die", "dem"], "why": "die Treppe，第三格 → der。", "zh": "电梯在哪儿？——在楼梯旁边。"}, {"id": "A1-39-04", "t": "type", "p": "p3", "q": "Wo ist Herr Müller? – In ___ Büro.", "a": "dem", "why": "das Büro，第三格 → dem（也可以说 im Büro）。", "hint": "das Büro，第三格"}, {"id": "A1-39-05", "t": "fix", "p": "p3", "s": "Die Toilette ist neben dem Treppe.", "bad": "dem", "a": "der", "o": ["die", "den"], "why": "die Treppe 是阴性，第三格 → der。", "zh": "厕所在楼梯旁边。"}, {"id": "A1-39-06", "t": "sort", "p": "p3", "q": "用 im 还是 in der？", "cats": ["im", "in der"], "items": [{"w": "Flur", "c": 0}, {"w": "Sekretariat", "c": 0}, {"w": "Besprechungsraum", "c": 0}, {"w": "Bibliothek", "c": 1}, {"w": "Kantine", "c": 1}, {"w": "Cafeteria", "c": 1}], "why": "阳性、中性：im（in dem）；阴性：in der。"}]}, "A1-40": {"p": ["p4"], "items": [{"id": "A1-40-01", "t": "pick", "p": "p4", "q": "Ich ___ weg von zu Hause.", "a": "will", "o": ["wollt", "willst"], "why": "ich will。", "zh": "我想离开家。"}, {"id": "A1-40-02", "t": "pick", "p": "p4", "q": "Und was ___ du hier machen?", "a": "willst", "o": ["will", "wollt"], "why": "du willst。", "zh": "那你想在这儿做什么？"}, {"id": "A1-40-03", "t": "pick", "p": "p4", "q": "Meine Eltern ___ das.", "a": "wollen", "o": ["will", "wollt"], "why": "sie（他们）wollen。", "zh": "我父母想要这样。"}, {"id": "A1-40-04", "t": "sort", "p": "p4", "q": "这句话该用哪个情态动词？", "cats": ["können（能 / 会）", "müssen（必须）", "wollen（想要）"], "items": [{"w": "我会游泳", "c": 0}, {"w": "他明天能来", "c": 0}, {"w": "我得工作", "c": 1}, {"w": "他必须去看医生", "c": 1}, {"w": "我想当厨师", "c": 2}, {"w": "她想去旅行", "c": 2}], "why": "能力和可能用 können，必要用 müssen，意愿用 wollen。"}, {"id": "A1-40-05", "t": "fix", "p": "p4", "s": "Nico wollt nicht studieren.", "bad": "wollt", "a": "will", "o": ["willst", "wollen"], "why": "er will；wollt 是 ihr 的形式。", "zh": "Nico 不想读大学。"}, {"id": "A1-40-06", "t": "trans", "p": "p4", "src": "Ich studiere nicht.", "cue": "加上 wollen", "q": "Ich will nicht ___.", "a": "studieren", "o": ["studiere", "studiert"], "why": "情态动词后用原形，放句尾。", "zh": "我不想读大学。"}]}, "A1-41": {"p": ["p1"], "items": [{"id": "A1-41-01", "t": "pick", "p": "p1", "q": "Ich kaufe im Supermarkt um die ___ ein.", "a": "Ecke", "o": ["Seite", "Straße"], "why": "um die Ecke = 在拐角那儿（离得很近）。", "zh": "我在拐角那家超市买东西。"}, {"id": "A1-41-02", "t": "pick", "p": "p1", "q": "Wo ist die Oper? – ___ der Nähe vom Bahnhof.", "a": "In", "o": ["An", "Bei"], "why": "固定说法：in der Nähe von …", "zh": "歌剧院在哪儿？——在火车站附近。"}, {"id": "A1-41-03", "t": "pick", "p": "p1", "q": "Die Post ist in der Nähe ___ Touristeninformation.", "a": "von der", "o": ["vom", "von dem"], "why": "die Touristeninformation 是阴性 → von der。", "zh": "邮局在游客问讯处附近。"}, {"id": "A1-41-04", "t": "fix", "p": "p1", "s": "Frau Kohlhaas wohnt in den Kälberstraße 4.", "bad": "den", "a": "der", "o": ["die", "dem"], "why": "die Straße，Wo? → in der。", "zh": "Kohlhaas 太太住在 Kälberstraße 4 号。"}, {"id": "A1-41-05", "t": "pick", "p": "p1", "q": "Ich arbeite ___ Bundesamt für Migration.", "a": "beim", "o": ["bei der", "bei den"], "why": "das Bundesamt，第三格 → bei dem = beim。", "zh": "我在联邦移民局工作。"}, {"id": "A1-41-06", "t": "trans", "p": "p1", "src": "Ich arbeite bei der Post.", "cue": "换成 das Rathaus", "q": "Ich arbeite ___ Rathaus.", "a": "beim", "o": ["bei der", "bei das"], "why": "das Rathaus → bei dem = beim。", "zh": "我在市政厅工作。"}]}, "A1-42": {"p": ["p2", "p4"], "items": [{"id": "A1-42-01", "t": "pick", "p": "p2", "q": "Der Fahrradladen ist ___ Zentrum.", "a": "im", "o": ["ins", "in die"], "why": "Wo? → im（in dem）Zentrum。", "zh": "自行车店在市中心。"}, {"id": "A1-42-02", "t": "pick", "p": "p2", "q": "Die Oper ist neben ___ Universität.", "a": "der", "o": ["die", "dem"], "why": "die Universität，Wo? → 第三格 der。", "zh": "歌剧院在大学旁边。"}, {"id": "A1-42-03", "t": "pick", "p": "p4", "q": "Gehen Sie bis ___ Kreuzung.", "a": "zur", "o": ["zum", "zu die"], "why": "bis zu + 第三格；die Kreuzung → zur。", "zh": "请走到十字路口。"}, {"id": "A1-42-04", "t": "order", "p": "p4", "tiles": ["Sie", "geradeaus", "Gehen", "immer"], "a": "Gehen Sie immer geradeaus.", "zh": "请一直往前走。", "why": "正式祈使句：动词第一，Sie 第二。"}, {"id": "A1-42-05", "t": "fix", "p": "p2", "s": "Ihr geht über dem Marktplatz.", "bad": "dem", "a": "den", "o": ["der", "das"], "why": "“走过”广场是方向，Wohin? → 第四格：über den Marktplatz。", "zh": "你们穿过集市广场。"}, {"id": "A1-42-06", "t": "pick", "p": "p4", "q": "Ist der Laden weit? – Nein, er ist ganz ___.", "a": "nah", "o": ["weit", "geradeaus"], "why": "weit（远）↔ nah（近）。", "zh": "店远吗？——不远，很近。"}]}, "A1-43": {"p": ["p3"], "items": [{"id": "A1-43-01", "t": "pick", "p": "p3", "q": "Fahrt ihr nicht mit ___ Bus?", "a": "dem", "o": ["den", "der"], "why": "mit + 第三格：mit dem Bus。", "zh": "你们不坐公交车吗？"}, {"id": "A1-43-02", "t": "pick", "p": "p3", "q": "Wir fahren mit ___ Straßenbahn.", "a": "der", "o": ["die", "dem"], "why": "die Straßenbahn，第三格 → der。", "zh": "我们坐有轨电车。"}, {"id": "A1-43-03", "t": "trans", "p": "p3", "src": "Ich fahre mit dem Auto.", "cue": "换成 die U-Bahn", "q": "Ich fahre mit ___ U-Bahn.", "a": "der", "o": ["die", "dem"], "why": "die U-Bahn → mit der U-Bahn。", "zh": "我坐地铁。"}, {"id": "A1-43-04", "t": "pick", "p": "p3", "q": "Wie ___ dauert die Fahrt?", "a": "lange", "o": ["viel", "weit"], "why": "问时长：Wie lange …?", "zh": "路上要多久？"}, {"id": "A1-43-05", "t": "fix", "p": "p3", "s": "Ich fahre mit den Zug.", "bad": "den", "a": "dem", "o": ["die", "der"], "why": "mit 后面永远是第三格：mit dem Zug。", "zh": "我坐火车。"}, {"id": "A1-43-06", "t": "sort", "p": "p3", "q": "mit dem 还是 mit der？", "cats": ["mit dem", "mit der"], "items": [{"w": "Bus", "c": 0}, {"w": "Zug", "c": 0}, {"w": "Fahrrad", "c": 0}, {"w": "U-Bahn", "c": 1}, {"w": "Straßenbahn", "c": 1}, {"w": "Bahn", "c": 1}], "why": "阳性、中性 → dem；阴性 → der。"}]}, "A1-44": {"p": ["p2"], "items": [{"id": "A1-44-01", "t": "pick", "p": "p2", "q": "Das Papier ist ___ Schrank.", "a": "im", "o": ["in den", "ins"], "why": "Wo? → 第三格：im Schrank。", "zh": "纸在柜子里。"}, {"id": "A1-44-02", "t": "pick", "p": "p2", "q": "Vielleicht ist es unter ___ Tastatur?", "a": "der", "o": ["die", "dem"], "why": "die Tastatur，Wo? → 第三格 der。", "zh": "也许在键盘下面？"}, {"id": "A1-44-03", "t": "pick", "p": "p2", "q": "Ich lege den Zettel auf ___ Tisch.", "a": "den", "o": ["dem", "der"], "why": "legen = 放到，Wohin? → 第四格 den。", "zh": "我把纸条放到桌上。"}, {"id": "A1-44-04", "t": "pick", "p": "p2", "q": "Hinter ___ Drucker ist nichts.", "a": "dem", "o": ["den", "der"], "why": "der Drucker，Wo? → 第三格 dem。", "zh": "打印机后面什么也没有。"}, {"id": "A1-44-05", "t": "trans", "p": "p2", "src": "Das Buch ist im Regal.", "cue": "改成“我把书放进书架”", "q": "Ich lege das Buch ___ Regal.", "a": "ins", "o": ["im", "in dem"], "why": "放到哪里 → 第四格：in das = ins。", "zh": "我把书放进书架。"}, {"id": "A1-44-06", "t": "type", "p": "p2", "q": "Die Stifte sind neben ___ Tastatur.", "a": "der", "why": "die Tastatur，Wo? → 第三格 der。", "hint": "die Tastatur，Wo?", "zh": "笔在键盘旁边。"}]}, "A1-45": {"p": ["p1"], "items": [{"id": "A1-45-01", "t": "pick", "p": "p1", "q": "Sind das die Birnen von Klara? – Nein, das sind ___ die Birnen von Klara.", "a": "nicht", "o": ["keine", "kein"], "why": "带定冠词的名词用 nicht 否定。", "zh": "这是 Klara 的梨吗？——不，不是 Klara 的梨。"}, {"id": "A1-45-02", "t": "pick", "p": "p1", "q": "Hast du Butter? – Nein, ich habe ___ Butter.", "a": "keine", "o": ["nicht", "kein"], "why": "没有冠词的名词用 kein-；die Butter → keine。", "zh": "你有黄油吗？——没有，我没有黄油。"}, {"id": "A1-45-03", "t": "trans", "p": "p1", "src": "Inge isst gern Birnen.", "cue": "改成否定", "q": "Inge isst ___ gern Birnen.", "a": "nicht", "o": ["kein", "keine"], "why": "否定 gern（副词）用 nicht，放在它前面。", "zh": "Inge 不喜欢吃梨。"}, {"id": "A1-45-04", "t": "fix", "p": "p1", "s": "Das ist nicht Käse, das ist Quark.", "bad": "nicht", "a": "kein", "o": ["keine", "keinen"], "why": "没有冠词的名词用 kein：kein Käse。", "zh": "这不是奶酪，这是夸克。"}, {"id": "A1-45-05", "t": "order", "p": "p1", "tiles": ["möchte", "nicht", "die", "Sie", "essen", "Birnen"], "a": "Sie möchte die Birnen nicht essen.", "zh": "她不想吃这些梨。", "why": "有原形动词时，nicht 放在原形 essen 前面。"}, {"id": "A1-45-06", "t": "sort", "p": "p1", "q": "用 nicht 还是 kein？", "cats": ["nicht", "kein"], "items": [{"w": "frisch", "c": 0}, {"w": "gern", "c": 0}, {"w": "die Birnen", "c": 0}, {"w": "Birnen", "c": 1}, {"w": "ein Apfel", "c": 1}, {"w": "Butter", "c": 1}], "why": "形容词、副词、带定冠词的名词用 nicht；带 ein 或没有冠词的名词用 kein。"}]}, "A1-46": {"p": ["p2"], "items": [{"id": "A1-46-01", "t": "pick", "p": "p2", "q": "Möchtest du Apfelsaft oder ___ eine Schorle?", "a": "lieber", "o": ["gern", "am liebsten"], "why": "二选一时用 lieber（更愿意）。", "zh": "你要苹果汁，还是更想要气泡水？"}, {"id": "A1-46-02", "t": "pick", "p": "p2", "q": "Welches Gericht isst du am ___?", "a": "liebsten", "o": ["lieber", "gernsten"], "why": "最高级：am liebsten。", "zh": "你最喜欢吃哪道菜？"}, {"id": "A1-46-03", "t": "pick", "p": "p2", "q": "Ich ___ keinen Kohlrabi.", "a": "mag", "o": ["magst", "mögt"], "why": "ich mag。", "zh": "我不喜欢苤蓝。"}, {"id": "A1-46-04", "t": "type", "p": "p2", "q": "gut → besser → am ___", "a": "besten", "why": "gut 的最高级：am besten。", "hint": "最高级"}, {"id": "A1-46-05", "t": "fix", "p": "p2", "s": "Ich trinke gerner Tee.", "bad": "gerner", "a": "lieber", "o": ["mehr", "besser"], "why": "gern 的比较级是 lieber，没有 gerner。", "zh": "我更喜欢喝茶。"}, {"id": "A1-46-06", "t": "pick", "p": "p2", "q": "___ Getränk möchtest du?", "a": "Welches", "o": ["Welcher", "Welche"], "why": "das Getränk 是中性 → welches。", "zh": "你想喝哪种饮料？"}]}, "A1-47": {"p": ["p3", "p4"], "items": [{"id": "A1-47-01", "t": "pick", "p": "p4", "q": "Möchtest du lieber ___?", "a": "abwaschen", "o": ["waschen ab", "abwäschst"], "why": "和情态动词连用：原形 abwaschen 放句尾。", "zh": "你更想洗碗吗？"}, {"id": "A1-47-02", "t": "pick", "p": "p4", "q": "Ich wasche lieber ___.", "a": "ab", "o": ["an", "aus"], "why": "abwaschen 单用时拆开：wasche … ab。", "zh": "我更愿意洗碗。"}, {"id": "A1-47-03", "t": "pick", "p": "p3", "q": "Nico putzt genauso ungern ___ Inge.", "a": "wie", "o": ["als", "so"], "why": "genauso + 原级要配 wie。", "zh": "Nico 和 Inge 一样不爱打扫。"}, {"id": "A1-47-04", "t": "pick", "p": "p3", "q": "Max putzt mehr ___ Inge.", "a": "als", "o": ["wie", "so"], "why": "比较级 mehr + als。", "zh": "Max 打扫得比 Inge 多。"}, {"id": "A1-47-05", "t": "fix", "p": "p3", "s": "Lisa schläft nicht so viel als Emma.", "bad": "als", "a": "wie", "o": ["so", "mehr"], "why": "nicht so + 原级 + wie。", "zh": "Lisa 睡得没有 Emma 多。"}, {"id": "A1-47-06", "t": "pick", "p": "p4", "q": "Ich sauge nicht so ___.（不太常）", "a": "oft", "o": ["häufiger", "nie"], "why": "nicht so oft = 不太经常。", "zh": "我不太常吸尘。"}]}, "A1-48": {"p": ["p4"], "items": [{"id": "A1-48-01", "t": "pick", "p": "p4", "q": "Gehst du gern ___?", "a": "schwimmen", "o": ["schwimmst", "schwimmt"], "why": "gehen + 原形：schwimmen gehen。", "zh": "你喜欢去游泳吗？"}, {"id": "A1-48-02", "t": "pick", "p": "p4", "q": "Max und Tarek gehen gern ___.", "a": "angeln", "o": ["angelt", "angeln gehen"], "why": "gehen 已经变位，第二个动词用原形。", "zh": "Max 和 Tarek 喜欢去钓鱼。"}, {"id": "A1-48-03", "t": "order", "p": "p4", "tiles": ["morgen", "gehe", "Ich", "arbeiten"], "a": "Ich gehe morgen arbeiten.", "zh": "我明天去上班。", "why": "gehen 变位第二位，arbeiten 原形放句尾。", "alt": ["Morgen gehe ich arbeiten."]}, {"id": "A1-48-04", "t": "pick", "p": "p4", "q": "Was ___ du in deiner Freizeit?", "a": "machst", "o": ["macht", "machen"], "why": "du machst；W 问句动词第二。", "zh": "你空闲时做什么？"}, {"id": "A1-48-05", "t": "trans", "p": "p4", "src": "Joggst du gern?", "cue": "改成“你喜欢去散步吗？”", "q": "Gehst du gern ___?", "a": "spazieren", "o": ["spazierst", "spaziert"], "why": "spazieren gehen：第二个动词用原形。", "zh": "你喜欢去散步吗？"}, {"id": "A1-48-06", "t": "fix", "p": "p4", "s": "Inge geht im Park spaziert.", "bad": "spaziert", "a": "spazieren", "o": ["spazierst", "spazierte"], "why": "gehen + 原形：spazieren。", "zh": "Inge 在公园散步。"}]}, "A1-49": {"p": ["p1", "p3"], "items": [{"id": "A1-49-01", "t": "pick", "p": "p1", "q": "ein ___ Mehl（1 公斤）", "a": "Kilo", "o": ["Liter", "Stück"], "why": "1 公斤 = ein Kilo。", "zh": "一公斤面粉"}, {"id": "A1-49-02", "t": "pick", "p": "p1", "q": "zwei ___ Mais（罐装）", "a": "Dosen", "o": ["Dose", "Dosens"], "why": "Dose 作单位要变复数：zwei Dosen。", "zh": "两罐玉米"}, {"id": "A1-49-03", "t": "pick", "p": "p3", "q": "Wir kaufen Fleisch ___ Metzgerei.", "a": "in der", "o": ["im", "auf der"], "why": "die Metzgerei → in der。", "zh": "我们在肉铺买肉。"}, {"id": "A1-49-04", "t": "fix", "p": "p1", "s": "Kannst du ein Pfund Tomate mitbringen?", "bad": "Tomate", "a": "Tomaten", "o": ["Tomates", "Tomatens"], "why": "可数的东西论重量买时用复数：ein Pfund Tomaten。", "zh": "你能带一磅番茄回来吗？"}, {"id": "A1-49-05", "t": "pick", "p": "p3", "q": "Max will Tarek nicht allein ___ Restaurant lassen.", "a": "im", "o": ["in die", "ins"], "why": "在哪里（Wo?）→ im Restaurant。", "zh": "Max 不想让 Tarek 一个人留在餐厅。"}, {"id": "A1-49-06", "t": "type", "p": "p1", "q": "500 g Butter = ein ___ Butter", "a": "Pfund", "why": "ein Pfund = 500 克。", "hint": "500 克"}]}, "A1-50": {"p": ["p2"], "items": [{"id": "A1-50-01", "t": "pick", "p": "p2", "q": "Was ___ es sein?", "a": "darf", "o": ["darfst", "dürfen"], "why": "店员常说：Was darf es sein?", "zh": "您要点什么？"}, {"id": "A1-50-02", "t": "pick", "p": "p2", "q": "Ich ___ gerne zwei Stück Apfelkuchen.", "a": "hätte", "o": ["habe", "hatte"], "why": "客气地要东西：Ich hätte gerne …", "zh": "我想要两块苹果蛋糕。"}, {"id": "A1-50-03", "t": "pick", "p": "p2", "q": "Ein Roggenbrot kostet 3,20 Euro. Und ein ___?", "a": "halbes", "o": ["halb", "halbe"], "why": "ein halbes Brot（das Brot，中性）。", "zh": "一个黑麦面包 3.20 欧元。那半个呢？"}, {"id": "A1-50-04", "t": "order", "p": "p2", "tiles": ["gerne", "hätte", "Ich", "Brot", "ein"], "a": "Ich hätte gerne ein Brot.", "zh": "我想要一个面包。", "why": "hätte 在第二位。", "alt": ["Gerne hätte ich ein Brot."]}, {"id": "A1-50-05", "t": "fix", "p": "p2", "s": "Darf es sonst noch was seid?", "bad": "seid", "a": "sein", "o": ["ist", "sind"], "why": "darf + 动词原形 sein。", "zh": "还要别的吗？"}, {"id": "A1-50-06", "t": "pick", "p": "p2", "q": "Haben Sie sonst noch einen Wunsch? – Nein, danke, das ist ___.", "a": "alles", "o": ["alle", "allen"], "why": "固定说法：Das ist alles。", "zh": "您还需要什么吗？——不用了，就这些。"}]}, "A1-51": {"p": ["p2", "p1"], "items": [{"id": "A1-51-01", "t": "pick", "p": "p2", "q": "Wie teuer ___ die Tomaten?", "a": "sind", "o": ["ist", "kostet"], "why": "die Tomaten 是复数 → sind。", "zh": "番茄多少钱？"}, {"id": "A1-51-02", "t": "pick", "p": "p2", "q": "Ein Kilo Bananen ___ 1,10 Euro.", "a": "kostet", "o": ["kosten", "kostest"], "why": "主语是 ein Kilo（单数）→ kostet。", "zh": "一公斤香蕉 1.10 欧元。"}, {"id": "A1-51-03", "t": "pick", "p": "p1", "q": "Ich hätte gern 300 ___ Datteln.", "a": "Gramm", "o": ["Gramme", "Gramms"], "why": "Gramm 作单位不变复数。", "zh": "我要 300 克枣。"}, {"id": "A1-51-04", "t": "type", "p": "p2", "q": "___ kosten die Tomaten?", "a": "Was", "why": "问价格：Was kosten …?（也可以说 Wie viel kosten …?）", "hint": "问价格的疑问词", "zh": "番茄多少钱？", "alt": ["Wie viel"]}, {"id": "A1-51-05", "t": "fix", "p": "p1", "s": "Ich nehme fünf Gurke.", "bad": "Gurke", "a": "Gurken", "o": ["Gurkes", "Gürken"], "why": "五根黄瓜：fünf Gurken（复数）。", "zh": "我要五根黄瓜。"}, {"id": "A1-51-06", "t": "sort", "p": "p2", "q": "用 kostet 还是 kosten？", "cats": ["kostet", "kosten"], "items": [{"w": "der Apfel", "c": 0}, {"w": "ein Pfund Tomaten", "c": 0}, {"w": "das Brot", "c": 0}, {"w": "die Gurken", "c": 1}, {"w": "die Datteln", "c": 1}, {"w": "fünf Brötchen", "c": 1}], "why": "单数主语 → kostet，复数主语 → kosten。ein Pfund Tomaten 的主语是 ein Pfund。"}]}, "A1-52": {"p": ["p4"], "items": [{"id": "A1-52-01", "t": "pick", "p": "p4", "q": "___ Sie die Tomaten in Würfel.", "a": "Schneiden", "o": ["Schneidet", "Schneide"], "why": "正式祈使句：Schneiden Sie …", "zh": "请把番茄切丁。"}, {"id": "A1-52-02", "t": "pick", "p": "p4", "q": "Den Teig in die Form ___.（菜谱写法）", "a": "geben", "o": ["gibt", "geben Sie"], "why": "不定式写法：原形放句尾，没有主语。", "zh": "把面团放进模具。"}, {"id": "A1-52-03", "t": "order", "p": "p4", "tiles": ["Sie", "den", "Legen", "Pizza", "auf", "Käse", "die"], "a": "Legen Sie den Käse auf die Pizza.", "zh": "请把奶酪放到比萨上。", "why": "正式祈使句：动词第一，Sie 第二。"}, {"id": "A1-52-04", "t": "trans", "p": "p4", "src": "Schneiden Sie die Zwiebeln.", "cue": "改成不定式写法", "q": "Die Zwiebeln ___.", "a": "schneiden", "o": ["schneiden Sie", "schneidet"], "why": "不定式写法：原形放句尾。", "zh": "切洋葱。"}, {"id": "A1-52-05", "t": "fix", "p": "p4", "s": "Schneidet Sie den Schinken klein.", "bad": "Schneidet", "a": "Schneiden", "o": ["Schneide", "Schneidest"], "why": "和 Sie 搭配的祈使句用 Schneiden。", "zh": "请把火腿切小。"}, {"id": "A1-52-06", "t": "pick", "p": "p4", "q": "Du ___ den Fetakäse in kleine Stücke.", "a": "schneidest", "o": ["schneidet", "schneiden"], "why": "du schneidest（词干以 d 结尾，加 -est）。", "zh": "你把羊奶酪切成小块。"}]}}};
